programs.sol:
"""Approximate the component's negative GL-spelling signal.

Look for GL inside a token, G|L split between tokens, and one further
continuation token. Short fragments and GLY/GLUC spellings are stronger;
familiar complete words are weaker. Split-off English -ly adverb endings
are exceptions. Greek/Cyrillic equivalents and Japanese グ|リ are included.
This is a spelling heuristic, not a predictor of the scattered positive fires.
"""
import re
from functools import lru_cache
import regex
import wordnet
from wordfreq import zipf_frequency

READS = ()


def gl_spelling(text):
    return text.lower().translate(str.maketrans('гγлλ', 'ggll'))


@lru_cache(maxsize=16384)
def familiarity(word):
    return max(zipf_frequency(word, lang)
               for lang in ('en', 'de', 'fr', 'it', 'es', 'ru'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, word, was_split, old_doc = carry or ('', '', False, None)
    if doc != old_doc:
        previous, word, was_split = '', '', False
    token = prefix.token_strings[-1]
    s, p = gl_spelling(token), gl_spelling(previous)
    new_word = re.split(r'[\W\d_]+', word + token.lower())[-1][-40:]
    rw = gl_spelling(new_word)
    inside = 'gl' in s
    split = p.endswith('g') and s.startswith('l')
    tail = ((('gl' in p and len(p.strip()) <= 4) or was_split)
            and s[:1].isalpha() and not token[:1].isspace())
    state = (token, new_word, split, doc)

    # This Japanese spelling has the same sharp split-token response.
    if previous.endswith(('グ', 'ぐ')) and token.startswith(('リ', 'り')):
        return state, -6.2
    if not (inside or split or tail):
        return state, -0.002

    f = familiarity(new_word)
    common = max(0.0, f - 3.0)
    n = min(len(s.strip()), 8)
    initial = rw.startswith('gl')
    cyrillic = bool(regex.search(r'\p{Script=Cyrillic}', previous + token))

    if split:
        value = (-4.66 + .69*f - .36*common + .41*n
                 - 1.32*initial - .38*cyrillic)
        if s == 'l':
            value -= 2.53
        if 'gly' in rw:
            value -= 2.96
        # GLY in a medical fragment differs from an ordinary -ly adverb.
        if s == 'ly' and (p.endswith('ing') or
                          'adverb' in wordnet.parts_of_speech(new_word)):
            value = -0.02
    elif inside:
        value = (-1.79 + .21*n + .23*common
                 - .19*initial + .26*cyrillic)
        if s.strip().endswith('gl'):
            value -= .32
        if s.strip().startswith(('gly', 'gluc')):
            value -= 2.50
    else:
        value = (-3.57 + .16*f - .13*common + .33*n
                 + .48*min(len(p.strip()), 8) + .38*initial)
        if p.endswith('gl'):
            value -= .87
            if s[:1] in 'aeiou' and len(s) <= 3:
                value -= 1.19
        if gl_spelling(word).endswith(('gly', 'gli', 'gluc')):
            value -= 1.79
    return state, min(0.0, value - .002)

"""A source-namespace detector, with a related file-opening response.

Emphasize the source side of Python's `from ... import`, standard Java,
C# and Rust namespaces, and `with open`. Imported object names are quiet.
The few named libraries below are Python's scientific/data-processing stack;
Python itself supplies the standard-library name set. Unmatched text is zero.
State is recent source text, reset at each document boundary. Exact strengths
vary by name and context; these rules deliberately use broad categories.
"""
import re
import sys

READS = ()
SCIENTIFIC = frozenset(('numpy', 'scipy', 'pandas', 'sklearn', 'torch',
    'tensorflow', 'keras', 'PIL', 'matplotlib', 'tqdm', 'bs4', 'gensim',
    'sympy', 'pylab', 'mpl_toolkits'))
MODULE_PARTS = frozenset(('core', 'models', 'utils', 'config', 'exceptions'))
JAVA_PACKAGES = frozenset(('awt', 'io', 'lang', 'math', 'net', 'nio',
    'sql', 'text', 'time', 'util'))
STATEMENT = re.compile(
    r'(?:^|[\s\'"`>;{#+-])\b(from|import|using|use)\s*([\w.:]*)$')


def python_source(token, path):
    word = token.strip()
    if word == 'import' and path:
        return 1.4
    if not path and token[:1].isspace():
        if word == '.':
            return 3.3
        if word.startswith('..'):
            return 0.7
        if word in sys.stdlib_module_names and word != '__future__':
            return 6.0
        if word in SCIENTIFIC:
            return 5.5
        if word in MODULE_PARTS:
            return 4.0
        if len(word) >= 2 and any(n.startswith(word) for n in SCIENTIFIC):
            return 3.7
        if re.fullmatch(r'[A-Za-z_]\w*', word):
            return 1.5
    elif path and token.startswith('.') and word[1:].islower():
        if path in SCIENTIFIC:
            return 3.0
        if word[1:] in sys.stdlib_module_names:
            return 2.0
        return 2.5 if word[1:] in MODULE_PARTS else 0.5
    elif path and re.fullmatch(r'\w+', token):
        if path + token in SCIENTIFIC:
            return 2.2
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, age = '', '', 0
    else:
        _, tail, previous, age = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    line = tail.rsplit('\n', 1)[-1].rsplit('\\n', 1)[-1]
    line = line.rsplit('<|endoftext|>', 1)[-1]
    match = STATEMENT.search(line)
    mode, path = (match.group(1), match.group(2)) if match else ('', '')
    if (mode == 'from' and match.start() > 0
            and line[match.start()] not in '\'"`#+-'):
        before = line[:match.start()].strip(' \\"\'`>#+-0123456789\t')
        if before:
            mode = ''  # Don't treat ordinary prose "from" as an import.
    value = python_source(token, path) if mode == 'from' else 0.0
    if mode == 'import' and path and token.startswith('.') and word[1:].islower():
        value = 0.35
    if mode == 'import' and path == 'java' and word[1:] in JAVA_PACKAGES:
        value = 3.2 if word in ('.net', '.math') else 2.0
    if mode == 'using':
        if not path and word == 'System':
            value = 3.5 if age == 1 else 2.0
        elif not path and word == 'std':
            value = 2.5
        elif path == 'std' and word == '::':
            value = 2.5
        elif path.startswith('System'):
            value = {'.Collections': 2.4, '.Linq': 0.9,
                '.ComponentModel': 2.0, '.RegularExpressions': 1.7}.get(word, 0.0)
    if mode == 'use':
        if not path and word in {'std', 'core', 'crate', 'self', 'super'}:
            value = 4.7 if word == 'std' else 1.8
        elif path == 'std::' and token.isidentifier():
            value = 1.5
        elif token in ('::', '::{'):
            value = 2.7 if path == 'std' else 1.2
    if previous.strip() == 'namespace' and word == 'std':
        value = 3.2
    if previous.strip() == 'with' and word == 'open':
        value = 6.0
    return (doc, (tail + token)[-180:], token, age + 1), value

"""A token-shape approximation, not a semantic topic detector.

Joined punctuation, word/punctuation mixtures, UTF-8 continuation pieces,
nonbreaking spaces and past auxiliaries tend to contribute positively.
Ordinary ASCII words are near zero, with small lexical-class exceptions.
Document starts get a negative baseline instead (stronger for Han text).
The constants summarize these readable classes in training text;
lexical and contextual differences inside a class remain unmodelled.
"""
import regex

READS = ()
CLOSE = ')]｝}］）'
OPEN = '([｛{［（'
DASH = '-–—−'
MATH = '=+^$%&|*<>'


def token_value(b):
    s = b.decode('utf-8', 'replace')
    w = s.strip()
    low = w.lower()
    newline = '\n' in s or '\r' in s
    punctuation = bool(w) and not any(c.isalnum() for c in w)

    if w.startswith('`'):
        return 0.82 if s.startswith(' ') else 0.05
    if punctuation and len(w) == 1 and s.startswith(' ') and not newline:
        if w in CLOSE:
            return 0.82
        if w in ',;:.':
            return 0.49

    if punctuation and len(w) > 1:
        if w[0] in CLOSE:
            if newline:
                return 0.19
            return 1.15 if w[-1] in OPEN else 0.69
        if w.startswith('.'):
            return 0.07 if newline else 0.69
        if not s.isascii():
            return 0.65
        return 0.47 if w[-1] in OPEN else 0.15

    if not s.isascii():
        if b and 128 <= b[0] < 192:
            return 0.62
        if '\xa0' in s:
            return 0.65
        if w.isupper():
            return 0.43
        return 0.45 if w and w[0] in DASH else 0.09

    mixed = any(c.isalpha() for c in w) and not w.isalpha()
    if mixed:
        if w.istitle():
            return 0.55
        if '_' in w:
            return -0.30 if w[0] in MATH else 0.01
        if w[0] in ',;:':
            return 0.78
        if w[0] in '/\\':
            return 0.32
        return 0.27 if w[0] in DASH else 0.10

    if low in {'was', 'were', 'had'}:
        return {'was': 0.67, 'were': 0.34, 'had': 0.58}[low]
    if '\0' in s:
        return 0.98
    if low in {'new', 'another'}:
        return 0.41
    if len(w) <= 3:
        if w and w[0] in CLOSE:
            return 0.42 if s.startswith(' ') else 0.07
        return 0.0
    if low in {'into', 'onto'}:
        return 0.46
    return 0.45 if s.startswith('\t') else -0.03


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    b = prefix.token_bytes[-1]
    if carry is None or carry != doc:
        # Attention resets at each packed document, including a row's start.
        text = b.decode('utf-8', 'replace')
        value = -1.51 if regex.search(r'\p{Script=Han}', text) else -0.74
    else:
        value = token_value(b)
    return doc, float(value)

"""A spelling-dependent pulse at the beginning of a document.

Most of this component's activity is on the first token, not on subsequent
occurrences of the same word. The pulse survives an initial run of identical
tokens. Its size depends on writing system and token shape; articles, copulas,
indentation and code punctuation have particularly strong pulses. The rules
below approximate these groups rather than memorize arbitrary vocabulary.
"""
import unicodedata

READS = ()
COPULAS = set('be am is are was were been being'.split())


def first_value(token):
    s = token.strip()
    if token.startswith('<|'):
        return 0.5
    if not s:
        if token == ' ':
            return -0.82
        if set(token) == {' '}:
            return 8.2 if len(token) <= 4 else 5.7
        if '\n' in token:
            return 2.5 if token.count('\n') == 1 else 1.2
        return 0.5
    if s.isdecimal():
        return -0.8
    lower = s.lower()
    spaced = token.startswith(' ')
    if lower == 'the':
        return 17.7 if spaced and s[0].isupper() else 6.5
    if lower == 'a':
        return 4.3 if spaced else 2.1
    if lower == 'an':
        return 6.0 if spaced else 4.8
    if lower in COPULAS and spaced and s.islower():
        return 6.2
    if lower == 'we':
        return 9.0 if spaced else 5.2
    if s in ('import', 'using', 'from'):
        return -0.6
    if s in ('package', 'class', 'function', 'def', 'return', 'public'):
        return 4.7
    script = unicodedata.name(s[0], '').split(' ')[0]
    if script == 'LATIN':
        if len(s) == 1:
            return 2.0
        return 2.5 if spaced or s[0].isupper() else 1.8
    if script in ('CJK', 'GREEK'):
        return -0.8
    if script == 'CYRILLIC':
        return 1.6
    if script in ('KATAKANA', 'HANGUL'):
        return 2.9
    if script == 'HIRAGANA':
        return 0.9
    if script in ('ARABIC', 'REPLACEMENT'):
        return 0.0
    if s[0] in '.,，、':
        return 1.5 if token.count('\n') == 1 else -0.2
    if s[0] == ';':
        return 8.0
    if '\n' in token:
        return 6.5 if any(c in s for c in '{}[]);:') else 3.5
    if s[0] == '#':
        return 4.2 if set(s) == {'#'} else 1.5
    if s.startswith('/*'):
        return 7.0
    if s == '/' or s.startswith('<?'):
        return 0.0
    if s[0] in '-=+|*`':
        return 3.1
    if s[0] in '([{<':
        return 0.5
    if s[0] in '\"“':
        return -1.5
    return 1.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = first_value(prefix.token_strings[-1])
        return (doc, token_id, value), value
    _, first_id, value = carry
    if token_id != first_id:
        value = 0.0  # Once the opening run ends, the pulse never restarts.
    return (doc, first_id, value), value

programs.haiku:
"""Document-opening token detector for layers.1.mlp.down_proj, component 3972.

What it does, in plain terms
- The component is essentially silent except on the first token of each document. A row
  packs several documents end to end, and the model restarts attention and positions at each
  one, so at a document's first token the component's output depends only on which token it
  is (checked: the same token gives the same value at every document start). Everywhere else
  its activation is near zero, so the program predicts 0 there.
- At a document's first token the program sorts the token into a word or symbol class a
  reader knows and returns that class's typical activation:
    * indentation (a run of spaces, as in code):                         strongly positive
    * articles, 'this', forms of 'be' (The, the, a, is, was, be):       strongly positive
    * sentence openers and instructions (Now, To, For, We, Step, Problem): positive
    * programming keywords and code-like tokens (int, void, def, package, ;, {, _name): positive
    * pronouns, prepositions, conjunctions, other ordinary words:        mildly positive
    * a single plain space, digits:                                     slightly negative
    * capitalised question words and auxiliaries (What, How, Is, Are, Can): about zero/negative
    * prose punctuation, Chinese text in general, special tokens such as <|im_start|>: about zero
    * verbs of analysis, explanation, evaluation and description
      (analyze, summarize, explain, compare; Chinese 分析, 概括, 阐述, 评价, 赞扬): negative
    * " The" (with its leading space) is the single largest case: strongly positive
    * the end-of-text token: strongly negative
"""

READS = ()

ARTICLES_BE = {"the", "a", "an", "this", "these", "those", "is", "was", "were", "be",
               "been", "being", "are", "am"}
OPENERS = {"now", "next", "step", "steps", "problem", "question", "find", "need", "notice",
           "after", "wait", "end", "last", "name", "we", "to", "for", "pre", "main", "example",
           "proof", "let", "if", "given", "consider"}
CODE_WORDS = {"int", "void", "def", "return", "function", "func", "string", "main", "pass",
              "class", "var", "let", "const", "null", "none", "true", "false", "self",
              "package", "include", "fn", "struct", "public", "private", "static", "new"}
PRONOUNS = {"i", "you", "he", "she", "it", "we", "they", "his", "her", "its", "our", "your",
            "their", "my", "me", "us", "them", "him"}
PREPOSITIONS = {"of", "and", "or", "but", "with", "by", "at", "from", "on", "in", "into",
                "about", "as", "there", "here", "that", "not", "so"}
QUESTION_WORDS = {"is", "are", "do", "does", "can", "will", "what", "how", "why", "which",
                  "where", "who", "when", "although", "though", "despite", "since", "yes",
                  "thank", "honestly", "should", "could", "would", "have", "has", "did"}
ANALYSIS_EN = {"analyze", "analyse", "analysis", "summarize", "summarise", "explain", "compare",
               "describe", "review", "discuss", "evaluate", "assess", "examine", "criticize",
               "praise", "translate", "address", "interpret", "investigate", "extend"}
ANALYSIS_ZH = ("分析", "概括", "阐述", "阐明", "叙述", "讲解", "说明", "介绍", "描述", "评价",
               "评测", "评定", "赞扬", "赞美", "称赞", "指责", "批评", "揭示", "揭露", "剖析",
               "归纳", "探讨", "审视", "论述", "刻画", "展现", "反映", "衡量", "鉴别", "讲述",
               "解释", "阐释", "总结", "论证")
CODE_SYMBOLS = set("_{}[];=<>#\\")
PROSE_PUNCT = set(",.:;!?()\"'“”[]-")


def is_code_like(core: str) -> bool:
    """Identifiers and symbols of code: dotted or underscored names, brackets, camelCase."""
    if any(ch in CODE_SYMBOLS for ch in core):
        return True
    return core.startswith(".") or any(a.islower() and b.isupper() for a, b in zip(core, core[1:]))


def word_value(token: str) -> float:
    """Typical activation at a document's first token, by word class."""
    core = token.strip()
    low = core.lower()
    if token == "":
        return 0.0
    if token == " ":
        return -0.8
    if core == "":
        return 7.3 if token.strip(" ") == "" else 2.5
    if token == "<|endoftext|>":
        return -9.7
    if token.startswith("<|"):
        return 0.5
    if core[0].isdigit():
        return -0.8
    if any(verb in core for verb in ANALYSIS_ZH):
        return -6.5
    if low in ANALYSIS_EN:
        return -3.0
    if token == " The":
        return 12.0  # the strongest opener: " The" with a leading space
    if core.isascii() and core.isalpha():
        if core[0].isupper() and low in QUESTION_WORDS:
            return -1.0
        if low in ARTICLES_BE:
            return 5.6
        if low in OPENERS:
            return 4.2
        if low in CODE_WORDS:
            return 3.4
        if low in PRONOUNS:
            return 2.3
        if low in PREPOSITIONS:
            return 1.8
        return 2.3 if core[0].isupper() else 1.8
    if any(ord(ch) > 0x2E80 for ch in core):
        return -0.25
    if is_code_like(core):
        return 2.5
    if core in PROSE_PUNCT:
        return -0.2
    return 1.6


def step(carry, prefix, upstream):
    """This position's activation: a word-class value at a document's first token, else 0."""
    position = prefix.position
    starts_document = position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return carry, 0.0
    return carry, float(word_value(prefix.token_strings[-1]))

programs.sol:
"""A spelling-boundary contrast, not a semantic country detector.

Short g/h syllables have signed responses: gu/go spellings tend negative,
while gay and some Vietnamese ng/h syllables tend positive. Country glyphs
and a few analogous Greek, Cyrillic and Arabic spellings are handled too.
A small set of document-opening syntax rules captures the context-free edge.
"""
import unicodedata as ud
from functools import lru_cache
READS = ()

@lru_cache(maxsize=8192)
def plain(s):
    return ''.join(c for c in ud.normalize('NFD', s.lower())
                   if not ud.combining(c))

@lru_cache(maxsize=8192)
def vietnamese(s):
    return (any(c in 'đĐăĂơƠưƯ' for c in s) or
            any(c in '\u0309\u0323' for c in ud.normalize('NFD', s)))

def activation(prev, s, vi, position=99):
    if s in ('国', '國', '국', ' 국'): return -2.1
    if s == ' Guy': return -2.0
    if s == ' guy': return -0.6
    if s.lower() == 'gu': return -0.6
    if vi and s.lower() in (' hay', ' ham'):
        return 5.9 if s.lower() == ' hay' else 2.8
    a, b = plain(prev), plain(s)
    if s and not s[0].isspace():
        if a.endswith('g'):
            if b == 'uy': return -3.3
            if b in ('ay', 'ays'):
                return 5.1 if a.strip() in ('ng', '-ng') else 2.1
            if not a.endswith('ing'):
                if b == 'he': return 0.9
                if b in ('han', 'ham'): return 1.5
                if b == 'oc': return -3.3
                if b == 'op': return -2.0
                if b in ('os', 'osp', 'ood', 'oy'): return -0.5
                if b in ('ua', 'ud', 'us', 'up'): return -0.4
                if b == 'ao': return -1.5
                if vi and b in ('ap', 'am', 'an', 'ang', 'in'):
                    return 1.5
        if a.endswith('h') and not a.endswith(('ch', 'sh', 'ph')):
            if b in ('uy', 'ua', 'ugo', 'ough', 'ought'): return -0.9
            if b in ('am', 'em', 'ay', 'ang', 'eng'): return 0.4
        if a.endswith('ge') and b in ('oc', 'op', 'om'): return -1.0
        if a.endswith('gu') and b in ('o', 'us', 'ang', 'oo'):
            return -4.2
        if a.endswith('qu') and b in ('ux', 'y', 'ay'): return -1.6
        if prev.lower().strip() == 'г' and s.lower() in ('ос', 'уд', 'ум', 'у', 'ё'):
            return -2.5
        if prev.lower().endswith(('γ', 'ι')) and s == 'α': return 0.5
        if prev.lower().endswith('γ') and s == 'ι': return 0.5
        if prev.endswith(('ع', 'غ', 'ق', 'گ')) and s in ('و', 'وا', 'وص'):
            return -2.5
    if position == 0:
        if s.startswith(('\\', '{\\')): return -1.2
        if s.startswith('#'): return -0.6
        if s.startswith(('/*', '//')): return -1.0
        if s.strip().isalpha() and s.istitle(): return -0.1
    if position == 1 and prev == 'Title' and s == ':':
        return -2.6
    return 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, 0)
    _, prev, vi, position = carry
    s = prefix.token_strings[-1]
    vi = max(0, vi - 1)
    if vietnamese(s): vi = min(512, vi + 150)
    value = activation(prev, s, vi > 0, position)
    return (doc, s, vi, position + 1), value

programs.haiku:
"""Layer 1 MLP down-projection, component 3973: a sparse, token-specific feature.

What it does, in plain terms: this component is quiet almost everywhere (|activation|
is below 0.1 on about 99.9% of tokens). When it fires, the trigger is nearly always a
specific token, or a token in a specific spot, not a general property of the text.
This program reproduces the strongest and most reliable of those triggers. The first
two concern the "country" word (guó / 國 / 国 / 국):

1. The single country character 国, 國 or 국: strongly negative, about -2.1.
2. The "guó" syllable of romanized Chinese (Zhōng|guó, Míng|guó): the fragment before
   ends in "gu" and the next is "o", "ó", "ò", "uo" or "uó": strongly negative, about -9.
3. Other word fragments that follow a fragment ending in "g" and are on a short list
   of o/u-initial pieces (g|uy, phag|oc|ytosis, g|op): negative, about -2.
4. Vietnamese " hay" ("or", as in "X hay Y"): positive, about +2.4.
5. The "ay" of Vietnamese "ngay" ("today / at once"), after "ng": positive, about +4.5.
6. The first token of a document. There attention sees only the token itself, so its
   value depends only on the token. Code and markup openers ("#", "//", "/*", "using",
   "import", ...) are negative, about -0.7; the article "The" is negative, about -0.6;
   sentence-opening pronouns ("I", "They", "We", "This", ...) are positive, about +0.5.

Every other position predicts 0. Most of the variance it leaves unexplained is spread
over many tokens with small, idiosyncratic values, so a readable rule set covers only
part of it.
"""

COUNTRY_CHARS = {"国", "國", "국"}
GUO_ENDINGS = {"o", "ó", "ò", "uo", "uó"}
G_CONTINUATIONS = {"oc", "op", "uy", "ux", "ua", "ao", "osp", "uk", "Gu", "gu", "OS", "UY"}
VIETNAMESE_OR = {" hay", " Hay"}
CODE_OPENERS = {"#", "##", "#include", "//", "/*", "/*\n", "using", "import", '"', "\t", "\\", "def", "function"}
PRONOUN_OPENERS = {"I", "You", "We", "They", "He", "It", "This", "If", "When", "Today", "My", "What"}

READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_document = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_document:
        if tok in CODE_OPENERS:
            return carry, -0.7
        if tok == "The":
            return carry, -0.6
        if tok in PRONOUN_OPENERS:
            return carry, 0.5
        return carry, 0.0
    if tok in COUNTRY_CHARS:
        return carry, -2.1
    prev = prefix.token_strings[-2].strip().lower()
    if prev.endswith("gu") and tok.strip().lower() in GUO_ENDINGS:
        return carry, -9.0
    if tok in G_CONTINUATIONS and prev.endswith("g"):
        return carry, -2.0
    if tok in VIETNAMESE_OR:
        return carry, 2.4
    if tok == "ay" and prev.endswith("ng"):
        return carry, 4.5
    return carry, 0.0

programs.sol:
"""Mostly a negative lexical detector for 投 and the Korean syllable 투.

Separate characters fire more strongly than fused words. 投 compounds differ:
input/devotion and submissions are strong; voting and investors are weaker.
Additional characters in a fused compound halve the negative pulse each time.
The response can spill onto the next Han character, particularly 稿 after 投.
Smaller rules cover English investment and Japanese ウ lengthening an o-vowel.
At document starts, longer alphabetic pieces have a small positive offset.
"""
import codecs
import regex

READS = ()
O_VOWEL_KANA = 'オコゴソゾトドノホボポモヨロヲ'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        decoder = codecs.getincrementaldecoder('utf-8')('replace')
        carry = (doc, decoder, '', 0.)
    _, decoder, previous, old_pulse = carry
    split = bool(decoder.getstate()[0])
    text = decoder.decode(prefix.token_bytes[-1])
    word = text.strip()
    pulse = 0.
    if '投' in word:
        if word == '投':
            pulse = -12.7 if split else -9.5
        elif '投入' in word:
            pulse = -4.1
        elif '投稿' in word:
            pulse = -3.8
        elif '网投' in word or '投放' in word:
            pulse = -4.2
        elif '投资者' in word or '投資者' in word:
            pulse = -1.4
        elif any(w in word for w in ('投票', '投诉', '投訴', '投影')):
            pulse = -1.3
        elif '投资' in word or '投資' in word:
            pulse = -2.7
        else:
            pulse = -2.5
        pulse *= .5 ** max(0, len(word) - 2)
    elif word == '투':
        pulse = -10.9 if split else -6.

    value = pulse
    if text == '稿':
        value += .85 * old_pulse
    elif regex.search(r'\p{Script=Han}', text):
        value += .1 * old_pulse
    elif regex.search(r'\p{Script=Hiragana}', text):
        value += .05 * old_pulse
    if word.lower() in ('investment', 'investments'):
        value -= .38
    if word == 'ウ' and previous and previous[-1] in O_VOWEL_KANA:
        value += 1.7 / len(previous)
    if first and word.isalpha():
        value += .03 * min(len(word), 8)
    return (doc, decoder, text, pulse), float(value)

