programs.sol:
"""Language-conditioned spelling fragments.

Recent completed words supply frequency-based evidence for a language. In
French, Romanian and Bulgarian contexts, word-internal a/а/я endings receive
positive values. Other fragments get smaller language-specific corrections;
Romanian definite-article endings and short i/u+t endings are separate groups.
Romanian and Bulgarian e endings, and Romanian prepositions, tend negative.
Paired middle dots have an independent negative response.
These are coarse training averages, not a full grammatical analysis.
"""
import math
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'fr', 'ro', 'bg', 'ru', 'lv', 'es',
             'it', 'pt', 'de', 'nl', 'pl', 'tr')

@lru_cache(maxsize=100000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)

ROMANIAN_PREPOSITIONS = frozenset(
    'de din cu spre pentru pe la in în prin fara fără despre'.split()
)

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, scores, previous = '', [0.] * len(LANGUAGES), ''
    else:
        _, word, scores, previous = carry
    for ch in token:
        if ch.isalpha():
            word = (word + ch.lower())[-40:]
        else:
            if len(word) > 1:
                scores = [s * .90 + f
                          for s, f in zip(scores, frequencies(word))]
            word = ''
    peak = max(scores)
    weights = [math.exp(.65 * (s - peak)) for s in scores]
    total = sum(weights)
    gates = [max(0., (w / total - .4) / .6) for w in weights]
    raw = token.strip()
    s = raw.lower()
    internal = bool(token and token[0].isalpha()
                    and previous and previous[-1].isalpha())
    # Responses: unclassified context, French, Romanian, Bulgarian.
    response = (-.001, -.001, -.001, -.001)
    if s.isalpha():
        if internal:
            if raw.endswith(('a', 'а', 'я')):
                response = (-.07, 1.44, 1.96, .52)
            elif s in ('ul', 'ului', 'ile', 'ele'):
                response = (-.08, .24, .88, -.08)
            elif s.endswith('t') and len(s) <= 3 and any(c in s for c in 'iu'):
                response = (-.04, .22, .37, -.04)
            elif raw.endswith(('e', 'е')):
                response = (.015, .007, -1.08, -.53)
            elif s.endswith('ai'):
                response = (-.025, .56, -.025, -.025)
            else:
                response = (0., 0., -.13, -.13)
        elif s in ROMANIAN_PREPOSITIONS:
            response = (0., 0., -.54, 0.)
        elif raw.endswith('a') and len(s) > 3 and frequencies(s)[1] < 5:
            response = (-.03, .43, 1.96, -.03)
        else:
            response = (0., -.008, 0., -.07)
    base, french, romanian, bulgarian = response
    value = base + sum(gates[j] * (v - base) for j, v in
                       zip((1, 2, 3), (french, romanian, bulgarian)))
    if raw == '··':
        value = -1.73
    return (doc, word, scores, token), float(value)

programs.haiku:
"""Enumeration-label delimiter detector (v7).

The component fires on the punctuation or indentation that follows a list label: a number
(or a single capital letter or roman numeral) standing alone at the start of a line, as in
"1.", "65)", or "12<TAB>" in a numbered listing. It is strongest on ")" and on a list's first
item, and on early lines of a document. It also fires on a number followed directly by a
capitalised word ("7.Compare") in run-together numbered questions.
"""
import re

READS = ()

LABEL = re.compile(r"\s*([1-9]\d{0,2}|\d?[A-Z]|[IVX]{1,4})[.)]?")
NUMBER = re.compile(r".*[^\w.,]\d{1,3}")
CAP_MERGED = re.compile(r"\.[A-Z]")
DIGIT_LABEL = re.compile(r"\s*[1-9]\d{0,2}[.)]?")


def _line_before(prefix):
    parts = []
    docs = prefix.document_ids
    for i in range(len(prefix.token_strings) - 2, -1, -1):
        s = prefix.token_strings[i]
        if "\n" in s or docs[i] != docs[-1]:
            break
        parts.append(s)
    return "".join(reversed(parts))


def _doc_position(prefix):
    docs = prefix.document_ids
    n = 0
    for i in range(len(docs) - 1, -1, -1):
        if docs[i] != docs[-1]:
            break
        n += 1
    return n


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    before = _line_before(prefix)
    early = _doc_position(prefix) < 100
    if LABEL.fullmatch(before):
        label = before.strip()
        if cur.startswith(")"):
            return carry, 3.5
        if CAP_MERGED.match(cur) and DIGIT_LABEL.fullmatch(before):
            return carry, 4.0 if early else 2.5
        if cur.startswith("."):
            value = 1.8 if label.startswith("1") and not label[1:2].isdigit() else 0.65
            return carry, value * (2 if early else 1)
        if cur.strip() == "" and cur and "\n" not in cur:
            return carry, 1.0 if early else 0.7
        return carry, 0.0
    if NUMBER.fullmatch(before) and CAP_MERGED.match(cur):
        return carry, 5.0 if early else 2.5
    return carry, 0.0

programs.sol:
"""Approximate alif-boundary pulses in Arabic-script text.

Short word-initial alif fragments, and the fragment following alif, are
negative. Definite articles, clitics, hamza/madda, and Persian spelling
change their strength. Medial yeh-alif, especially yeh-alif-ba, is positive.
Recent Persian-specific letters provide a spelling-context heuristic.
The Arabic rule is damped at document starts; state resets there.
Most other tokens are zero; chat delimiters have small fixed offsets.
"""
import regex
READS = ()
ALIFS = 'اأإآ'
PROTOCOL = {
    '<think>': .93, '</think>': -.31,
    '<|im_start|>': -.14, '<|im_end|>': .10,
    '</tool_response>': .75, '</tool_call>': -.15,
}


def alif_value(s, previous, word, persian):
    t = s.strip()
    if not t or not regex.search(r'\p{Script=Arabic}', t):
        return 0.
    attached = bool(word) and not s[:1].isspace()
    word = word if attached else ''
    value, offset = 0., 0
    article = regex.match(r'[وفبك]?ال', t) if not word else None
    if article:
        value = -1.5 if t == 'ال' else 0.
        offset = article.end()
    for j in range(offset, len(t)):
        c = t[j]
        if c not in ALIFS:
            continue
        before, size = word+t[:j], min(len(t)-j-1, 3)
        article = bool(regex.fullmatch(r'[وفبك]?ال|[وفبك]?لل', before))
        clitic = len(before) == 1 and before in 'وفبكل'
        if c != 'ا':
            if not before or article or clitic:
                value -= (.4 if persian else 1.) if c == 'آ' else 1.5
                if size >= 2:
                    value += .8 if c != 'آ' else 0.
        elif not before:
            value += (-2.6, -3.1, -2., -.6)[size] if persian else (
                -4.7, -4., -2.5, -.6)[size]
            if not s[:1].isspace():
                value -= 1.
            if size == 1 and t[j+1] in 'ويی':
                value += 1.8
            if t.startswith('است') and persian:
                value += 1.
        elif article:
            value += (-2.8, -3.6, -3.3, -.4)[size] if persian else (
                -5.6, -7.8, -3.3, -.4)[size]
        elif clitic:
            if j == 0:
                value += (-2.1, -2.5, -1.9, -.5)[size] if persian else (
                    -2.1, -5.5, -2.3, -.5)[size]
            else:
                value += (-.7 if persian else -2.2) if size == 0 else -.5
                if before == 'ل':
                    value -= .6 if persian else 1.3
                if before == 'و':
                    value -= 1.2 if persian else 2.
        elif j == 0 and before[-1] in 'يی':
            value += 4.9 if t.startswith('اب') else 1.1
        break
    if attached:
        for back, c in enumerate(previous[-2:][::-1]):
            if c not in ALIFS:
                continue
            if back == 0:
                if c == 'ا':
                    pulse = -1.3 if persian else -2.1
                elif c == 'آ':
                    pulse = -.3 if persian else -1.2
                else:
                    pulse = -1.1 if persian and c == 'أ' else -3.2
                value += pulse / (1 + .4*(len(t)-1))
                if c == 'ا' and regex.fullmatch(r'[وفبكل]?(?:ال)?ا', word):
                    value -= 1.9 if persian else 3.3
                if t[0] in 'ويیهةز':  # glides, endings, Persian az
                    value += 1.4
            elif c in 'اأ':
                value -= .3
            break
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, word, history = ('', '', '') if first else carry[1:]
    s = prefix.token_strings[-1]
    persian = any(c in history+s for c in 'پچژگکی')
    value = alif_value(s, previous, word, persian) * (.7 if first else 1.)
    value += PROTOCOL.get(s, 0.)
    if first and s == '<|im_start|>':
        value = .36
    word = regex.split(r'[^\p{Script=Arabic}\p{M}]', word+s)[-1][-30:]
    return (doc, s, word, (history+s)[-160:]), float(value)

programs.haiku:
"""Alef-initial Arabic-script pieces push this component negative; chat markup tags push it
positive or slightly negative.

The component is near zero on most text. Its clearest responses are on Arabic and Persian
script tokens. The biggest are word-initial alef-family letters (ا أ إ آ), the usual start of
the article ال:
- a bare word-initial alef-family letter, or the article ال alone: strongly negative;
- a longer word-initial piece starting with ال or an alef: negative, the ال ones weakly;
- a piece with no leading space that continues a word right after a split-off article
  (ال or ا) or bare alef, as in "ال | ختبار": strongly negative;
- other Arabic word-internal pieces: slightly negative.
Chat-template tags are modest: <think> and </tool_response> positive, </think> negative.
Everything else is 0. The values are the mean activations of each group, measured on training
rows, so the program captures the sign and rough size of the component's response, not its
exact per-token values.
"""
import re

READS = ()

ARABIC = re.compile(r"[؀-ۿݐ-ݿﭐ-﷿ﹰ-﻿]")
ALEF_FAMILY = "اأإآ"
ARTICLE_PIECES = ("ال", "ا", "أ", "إ", "آ")
TAG_VALUES = {"<think>": 0.9, "</tool_response>": 0.75, "</think>": -0.3}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in TAG_VALUES:
        return carry, TAG_VALUES[tok]
    if not ARABIC.search(tok):
        return carry, 0.0
    word_start = tok.startswith(" ")
    body = tok.lstrip(" ")
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip() if same_doc else ""
    if not word_start and prev in ARTICLE_PIECES:
        return carry, -2.0
    if word_start and body.startswith("ال"):
        return carry, (-2.0 if len(body) == 2 else -0.3)
    if body[:1] in ALEF_FAMILY:
        if word_start:
            return carry, (-2.1 if len(body) == 1 else -1.1)
        return carry, -0.35
    return carry, (-0.02 if word_start else -0.2)

programs.sol:
"""A sparse approximation centered on document openings.

Use a negative first-token baseline, distinguished by character type, with
an exception for an initial class declaration. On the second token, match
literal opening patterns: 12, Title:, Hydro-, Posted on, a template bracket,
and a JavaScript anonymous function. An early C-comment colon decoration
also receives a positive value. Other activity is approximated by zero;
this omits substantial small, context-dependent fluctuations.
"""
READS = ()

# Token pairs spelling recognizable document-opening patterns.
OPENINGS = {
    ('1', '2'): 6.74,
    ('Title', ':'): -7.94,
    ('Hy', 'dro'): 9.65,
    ('Posted', ' on'): 4.88,
    ('{', '['): 3.94,
    ('(function', ' ()'): 5.12,
}


def first_token_value(token):
    if token == 'class':
        return 1.89
    if token.startswith('<|'):
        return -0.03
    if token.isspace():
        return -0.12
    if token.isdigit():
        return -0.17
    if token.isalpha():
        return -0.34
    return -0.24


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, first = 0, token
    else:
        position, first = carry[1] + 1, carry[2]

    value = 0.0
    if position == 0:
        value = first_token_value(token)
    elif position == 1:
        value = OPENINGS.get((first, token), 0.0)
    if first == '/*' and position < 20 and token.strip() == ':' * 8:
        value = 0.98
    return (doc, position, first), value

"""A local grammar approximation: clause links, pronoun--copula pairs,
negation, and the two uses of 'as'.  Most ordinary content words stay near
zero.  Capitalization distinguishes sentence-opening uses of function words.
At the first token of a document, use a small positive baseline instead.
This leaves much of the component's longer-context variation unexplained.
"""
import re

READS = ()
CLAUSE_WORDS = {
    'that': -0.28, 'which': -0.42, 'this': -0.19,
    'if': -0.25, 'though': -0.25, 'although': -0.56,
    'whatever': -0.35, 'whether': -0.31, 'what': -0.25,
    'where': -0.08, 'when': -0.09, 'why': -0.28,
    'while': -0.12, 'than': -0.04, 'such': -0.16,
}
AUXILIARIES = {
    'is': -0.01, 'was': 0.01, 'are': -0.04, 'am': -0.20,
    'were': 0.01, 'be': -0.02, 'been': 0.01,
    'must': -0.17, 'could': -0.21, 'would': -0.10,
    'should': -0.10, 'can': -0.03, 'cannot': -0.31,
    'has': -0.03, 'have': -0.02, 'had': -0.04,
}
PREPOSITIONS = set('in on at of from with by under through into'.split())
LABELING = set(
    'known defined expressed regarded considered treated serve serves served'.split()
)
REPORTING = set(
    'said says stated states found revealed indicated indicates mentions'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    raw = text.strip()
    match = re.fullmatch(r'[\s\"\'(]*([A-Za-z]+)', raw)
    spelling = match[1] if match else raw
    word = spelling.lower()
    p = previous.lower()
    capital = spelling[:1].isupper()
    comma = previous.endswith(',')
    value = CLAUSE_WORDS.get(word, AUXILIARIES.get(word, 0.0))

    if word in ('is', 'was'):
        if p == 'it':
            value = -1.10 if word == 'is' else -0.78
            if previous[:1].isupper():
                value -= 0.22
        elif p == 'there':
            value = -0.35 if word == 'is' else -0.26
        elif p == 'this':
            value = -0.34 if word == 'is' else -0.54
        elif p == 'that':
            value = -0.17 if word == 'is' else -0.07
        elif word == 'is' and p in ('he', 'she', 'what', 'and'):
            value = -0.20
        elif p == 'which':
            value = 0.07
    elif word == 'am':
        value = -0.40 if p == 'i' else 0.0
    elif word == 'are':
        if p in ('we', 'you', 'they', 'these'):
            value = -0.30 if p == 'we' else -0.20
        elif p == 'there':
            value = -0.11
        elif p == 'which':
            value = 0.11
    elif word == 'have':
        value = -0.14 if p in ('i', 'we', 'you') else 0.0
    elif word == 'has' and p in ('it', 'this'):
        value = -0.18
    elif word == 'be' and p in ('will', 'would'):
        value = -0.11
    elif word in ('can', 'could', 'would', 'should', 'must'):
        if p in ('how', 'what', 'why'):
            value = -0.70
        elif p == 'it':
            value = -0.40 if word in ('could', 'would') else -0.20
    elif word == 'as':
        value = 0.22
        if capital:
            value = -0.38
        elif comma or p in ('and', 'or', 'just'):
            value = -0.75
        elif p in LABELING or p in ('such', 'well'):
            value = -0.04
        elif p in ('are', 'be', 'not', 'used', 'much', 'far', 'soon'):
            value = 0.65
        elif not text[:1].isspace():
            value = -0.10
    elif word == 'that':
        if p == 'and':
            value = -0.92
        elif comma or p in ('for', 'but', 'so', 'fact'):
            value = -0.50
        elif p in PREPOSITIONS or p == 'such':
            value = 0.02
        elif p in REPORTING:
            value = 0.0
        elif capital:
            value = -0.38
    elif word == 'which':
        if p in ('and', 'that'):
            value = -0.90
        elif p in ('for', 'to', 'of') or comma:
            value = -0.55
        elif p in PREPOSITIONS:
            value = -0.18
    elif word == 'not':
        value = -0.03
        if p in AUXILIARIES or p in ('do', 'does', 'did', 'will', 'shall', 'need'):
            value = -0.27
        if p in ('was', 'were', 'would', 'could', 'should',
                 'have', 'has', 'had', 'need'):
            value = -0.64
    elif word == 'if':
        if previous.isspace() or not previous:
            value = 0.0
        elif comma or p in ('and', 'or', 'that'):
            value = -0.62
        elif p == 'as':
            value = -1.08
        elif p in ('check', 'checks', 'only', 'else', 'know'):
            value = 0.0
    elif word == 'this':
        if p == 'and':
            value = -0.77
        elif p in ('is', 'for', 'but'):
            value = -0.47
        elif p in ('with', 'from', 'by', 'like', 'about', 'use', 'do'):
            value = -0.04
    elif word == 'it':
        value = -0.03
        if p == 'is':
            value = -0.60
        elif p == 'for':
            value = -0.42
        elif p in ('and', 'as', 'which'):
            value = -0.24
    elif word == 'though':
        if p == 'even':
            value = 0.17
        elif comma or p == 'as':
            value = -0.65
        elif p == 'and':
            value = -0.90
    elif word == 'like':
        value = 0.18
    elif raw in ('?', '!'):
        value = -0.10
    elif raw == '.':
        value = 0.01 if p.isdigit() else -0.04

    if carry is None or carry[0] != doc:
        value = 0.24
    return (doc, spelling if word.isalpha() else raw), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:3981 as a clause-opener detector (negative) with mild positives.

What it does: the component's activation is mostly near zero, and goes strongly negative
where the text opens a new clause or subordinate construction. Its biggest negatives are the
expletive subject "It is/was ..." (the "is" after "it"), and a clause-initial "As" or "That"
after a comma or sentence start. Clearly negative too: relative "which/whom/whose", "that"
as a complementizer ("I think that ..."), subordinators (if, though, unless, whether...),
foreign clause words (que, si, die, nicht), and sentence-initial connectives (Thus, Perhaps,
Even). Mildly negative: "is/was/are", "not/this/such", modals, what/how/why/who/where.
Mildly positive: "as" used as a role or comparison after a participle or be-verb ("used as",
"are as", "not as"), "like" as a preposition, contractions ("I'm", "I've"), and the first
token of a document or row. Every other token is predicted 0.

Each token is classified from the current token and the one before it, with a fixed value per
class (the class means measured on training text). The rest of the activation's variance is
token-specific and not captured here."""

READS = ()

BOUNDARY = {",", ".", "?", "!", ";", ":", "\n", '"', "(", "<|endoftext|>"}
IT_BE = {"is", "was"}
AUX = {"could", "would", "should", "has", "had", "can", "will", "may", "might", "must", "have"}
WH = {"which", "whom", "whose"}
SUBORD = {"if", "though", "although", "unless", "whether", "while", "when", "because",
          "since", "once", "until", "whereas", "nor", "lest"}
NEG_DEM = {"not", "this", "such", "these", "those", "never", "no"}
BE = {"is", "are", "was", "were", "be", "am"}
MODAL = {"could", "would", "should", "must", "might"}
WH_Q = {"what", "how", "why", "who", "where"}
FOREIGN = {"que", "si", "die", "sich", "nicht", "daß", "dass", "qui", "che", "det", "doch", "comme"}
DISCOURSE = {"thus", "perhaps", "even", "see", "nothing", "cannot"}
CONTRACTION = {"'m", "’m", "'ve", "'ll"}
QUESTION = {"?", "？"}

ROLE_BEFORE_AS = {"be", "are", "is", "not", "far", "soon", "much", "same", "work", "use", "given", "shown"}

VALUES = {
    "as_role": 0.5,
    "start": 0.22, "it_is": -1.05, "it_aux": -0.17, "as_clause": -0.65, "as_other": 0.09,
    "that_clause": -0.5, "that_other": -0.26, "wh": -0.4, "subord": -0.14,
    "neg_dem": -0.14, "be": -0.05, "modal": -0.15, "wh_q": -0.2, "foreign": -0.3,
    "discourse": -0.3, "contraction": 0.2, "question": -0.11, "like": 0.19, "other": 0.0,
}


def category(cur, prev, first):
    if first or prev == "<|endoftext|>":
        return "start"
    if prev == "it" and cur in IT_BE:
        return "it_is"
    if prev == "it" and cur in AUX:
        return "it_aux"
    if cur == "as":
        if prev in BOUNDARY:
            return "as_clause"
        if prev.endswith("ed") or prev in ROLE_BEFORE_AS:
            return "as_role"
        return "as_other"
    if cur == "that":
        return "that_clause" if prev in BOUNDARY else "that_other"
    if cur in WH:
        return "wh"
    if cur in SUBORD:
        return "subord"
    if cur in NEG_DEM:
        return "neg_dem"
    if cur in BE:
        return "be"
    if cur in MODAL:
        return "modal"
    if cur in WH_Q:
        return "wh_q"
    if cur in FOREIGN:
        return "foreign"
    if cur in DISCOURSE and prev in BOUNDARY:
        return "discourse"
    if cur in CONTRACTION:
        return "contraction"
    if cur in QUESTION:
        return "question"
    if cur == "like":
        return "like"
    return "other"


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    first = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    return None, VALUES[category(cur, prev, first)]

programs.sol:
"""Approximate a sparse document-opening grammar signal.

Predict a pulse on the opening token, continuing it only while that token
repeats. I/we/you/they, infinitival 'to', lower-case modals, and detected
plural nouns tend to get positive values; most other openers get negative
ones. Word classes and typography supply coarse amplitude corrections.
Inflect plus WordNet identify plurals, rejecting spurious short stems.
After the opening run predict zero: finer lexical variation and the small
context-dependent tail are deliberately left unexplained.
"""
from functools import lru_cache
import inflect
import wordnet

READS = ()
_INFLECT = inflect.engine()
MODALS = frozenset('can could may might must shall should will would'.split())
NOT_PLURALS = frozenset(
    'is was has his this as yes does us news various perhaps'.split()
)
PREPOSITIONS = frozenset(
    'of in on at for from with by as into under over between after before '
    'during since through about per'.split()
)
CODE_DECLARATIONS = frozenset(
    'package import using class def int char const float double struct typedef'.split()
)


@lru_cache(maxsize=8192)
def opening_value(token):
    word = token.strip()
    low = word.lower()
    capital = word.istitle() and not token.startswith(' ')
    if token.startswith('<|'):
        return -1.2
    if not word:
        if '\t' in token:
            return 3.8
        return -2.55 if token == ' ' else -0.2
    if word.isdecimal():
        return -0.3 if word in {'0', '1'} else -3.0
    if low in {'we', 'you', 'they', 'to'}:
        return 17.5 if capital else 12.0
    if word == 'I':
        return 9.4 if token == 'I' else 6.2
    if low in MODALS and word.islower():
        return 10.5
    if low in {'not', "n't", "'t", '’t'} and not word.istitle():
        return 5.0
    if low in {'these', 'those'}:
        return 4.0
    if low in {'first', '1st'}:
        return 5.0
    if low in {'that', 'which', 'who'} and word.islower():
        return 2.5
    if low in {'and', 'or', 'but', 'nor', 'yet'}:
        return 0.0
    if low in {'package', 'using', 'namespace'}:
        return -10.5
    if low in CODE_DECLARATIONS:
        return -6.5
    if word.isalpha() and word.isascii() and low not in NOT_PLURALS:
        singular = _INFLECT.singular_noun(low)
        if (singular and len(singular) >= 3
                and 'noun' in wordnet.parts_of_speech(singular)
                and (not low.endswith('s')
                     or singular in wordnet.base_forms(low))):
            return 7.5
    if low in {'s', 'es', 'ers', 'ors', 'ants', 'ments', 'ons'}:
        return 5.0
    if '\n' in token or '\r' in token:
        return -1.0
    if low in PREPOSITIONS:
        return -4.6
    if low in {'a', 'an', 'the'}:
        return -3.3
    if word.isalpha():
        if not word.isascii():
            return -2.5
        if len(word) == 1:
            return -2.0
        value = -3.8 if word.istitle() else -3.1
        return value + (0.7 if token.startswith(' ') else 0.0)
    return -2.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(prefix.token_strings[-1])
        return (doc, token, True, value), value
    _, first, opening, value = carry
    opening = opening and token == first
    return (doc, first, opening, value), value if opening else 0.0

programs.haiku:
"""layers.1.mlp.down_proj:3983 -- "a bare verb comes next" at the start of a document.

What it does
  The component is silent (about 0) almost everywhere. It fires at the first token of a
  document, where attention can see nothing but that token, so its value is a fixed
  function of the word itself. It promotes base-form verbs in the next-token distribution
  (classify, define, occur, are) and suppresses forms like "has" or "started". So its
  sign says whether a plain verb is expected next:
    - subject pronouns We/They/You/I, modals (must, can, will), "to", "please"
      and plural nouns (Students, Experts, Cars): strongly positive, up to about +19;
    - prepositions and determiners (of, in, the, This, On): negative, about -4;
    - code keywords (package, import, def, from, using) and all-caps words: strongly
      negative, about -3 to -11, since a name or identifier follows;
    - other short words are about -3, long words about 0.
  A repeated middle-dot filler token '··' has a constant -7.13 wherever it occurs.

What it does not capture
  Individual words vary within these classes, and the table of exact values per token
  would explain the rest. Only the concept classes are written here.
"""
READS = ()

SUBJECT_PRONOUNS = {"We", "They", "You", "I", "you", "we", "they"}   # then a base verb
TO_PLEASE = {"to", "To", "please", "Please"}                         # 'to do', imperative
MODALS = {"can", "will", "must", "should", "could", "would", "may", "might", "shall", "cannot"}
MILD_POSITIVE = {"that", "who", "which", "not", "also", "some"}      # clause starters
PREP_DET = {"of", "in", "on", "at", "for", "with", "by", "from", "about", "over", "under", "into",
            "the", "this", "an", "my", "our", "your", "their", "its", "his", "her"}
IMPERATIVE = {"use", "make", "get", "take", "find", "create", "add", "run", "set", "build", "write"}
CODE = {"import", "def", "class", "package", "using", "from", "int", "select", "var", "let", "const",
        "public", "private", "include", "pragma"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s == "··":
        return None, -7.13
    if len(prefix.token_ids) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        return None, 0.0
    w = s.strip()
    l = w.lower()
    if w in SUBJECT_PRONOUNS or w in TO_PLEASE:
        return None, 13.0
    if l in CODE:
        return None, -9.0
    if l in MODALS:
        return None, 10.0
    if l in PREP_DET:
        return None, -4.0
    if l in IMPERATIVE:
        return None, -5.0
    if l in MILD_POSITIVE:
        return None, 3.0
    if w.isalpha() and w.isupper() and len(w) > 1:
        return None, -3.0
    if w.isalpha():
        if l.endswith("s") and not l.endswith("ss") and len(l) > 3:
            return None, 6.0
        if len(w) <= 4:
            return None, -3.0
        if len(w) <= 6:
            return None, -1.0
        return None, 0.0
    return None, -2.0

programs.sol:
"""Approximate boundary and token-form biases, not a semantic detector.

At document starts, hash signs and space-prefixed English articles get
positive values; other tokens get negative values, more so for non-ASCII
text. Away from boundaries, predictions stay near zero with small case,
length, newline, digit, and -ly suffix offsets. Most of this component's
token-specific variation is deliberately left unexplained.
"""

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry != document
    text = prefix.token_strings[-1]
    word = text.strip()
    if first:
        if word and all(c == '#' for c in word):
            value = 0.42
        elif word.lower() in ('a', 'an', 'the'):
            value = 0.35 if text.startswith(' ') else -0.06
        elif not text.isascii():
            value = -0.24
        else:
            value = -0.11
    elif word.isupper():
        value = 0.006
    elif word.lower().endswith('ly'):
        value = 0.010
    elif len(word) > 2:
        value = 0.000
    elif '\n' in text:
        value = -0.006
    elif any(c.isalpha() for c in word):
        value = -0.004
    elif word.isdigit():
        value = -0.0025
    else:
        value = 0.001
    return document, value

programs.haiku:
"""layers.1.mlp.down_proj:3986: a weak, mostly token-driven component.

Its activation is small and sign-varying almost everywhere (std about 0.04). What it
does track is a few words of the model's own deliberation:
  * "Wait" / "wait" / "await" / "waiting" and "Hmm", "see" and "<think>" push it up
    (about +0.1 to +0.3; "Wait" is the most reliable, about +0.29);
  * hedges "maybe" and "perhaps" push it slightly down (about -0.08);
  * a run of the middle-dot filler "··" (a degenerate repeated line) gives about -0.75.
Every other token is predicted as 0. The rule reads only the newest token, so it needs
no carry and no upstream components.
"""

READS = ()

REFLECTIVE = {
    "Wait": 0.29, " Wait": 0.30, "wait": 0.25, " wait": 0.25,
    "await": 0.22, "waiting": 0.18, " waiting": 0.18,
    "see": 0.17, " see": 0.17, "See": 0.10, " See": 0.10,
    "Hmm": 0.08, " Hmm": 0.08, "<think>": 0.09, "<tool_response>": 0.10,
}
HEDGES = {" maybe": -0.09, " perhaps": -0.07, "maybe": -0.09, "perhaps": -0.07}
DOT_FILLER = "··"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == DOT_FILLER:
        return carry, -0.75
    if token in REFLECTIVE:
        return carry, REFLECTIVE[token]
    if token in HEDGES:
        return carry, HEDGES[token]
    return carry, 0.0

programs.sol:
"""Approximate a tokenization-sensitive response to code member selection.

A closing call or index followed by a dot is negative in code, not in ordinary
parenthetical prose. Arrows and scope separators have weaker responses. The
history is bounded and reset between documents. Paired middle dots and
initial numerals (especially '12') are separate positive training patterns.
"""
import re

READS = ()

_CODE_CUES = (
    re.compile(r'[;{}]'),
    re.compile(r'(?<![=!<>])=(?!=)'),
    re.compile(r'\b(?:return|const|var|def|func|class|public|private|function)\b'),
    re.compile(r'[a-z][A-Z]|[A-Za-z][A-Za-z0-9]*_[A-Za-z_]'),
    re.compile(r'(?:[A-Za-z_]\w*|[)\]])\.[A-Za-z_]'),
    re.compile(r'\$[A-Za-z_]|&&|\|\||==|!=|::|->'),
)
_MATH = re.compile(
    r'\\(?:frac|sqrt|left|right|begin|end|[()])|[_^]\{|\w\^\w|[²³]'
    r'|(?<![\w.])(?:sqrt|sin|cos|tan|ln|gcd)\('
)
_CLOSERS = re.compile(r'''[()\[\]{}'"`!>]+\.$''')


def code_context(text):
    if '§' in text or 'C.F.R.' in text:
        return False
    cues = sum(bool(rule.search(text)) for rule in _CODE_CUES)
    if _MATH.search(text) and not re.search(r';|\breturn\b', text):
        return False
    return cues >= 2 or bool(re.search(r'[A-Za-z_]\w*\.[A-Za-z_]\w*\(', text))


def closes_access(text):
    """Does the last bracket close a call or an index, rather than prose?"""
    text = text.rstrip()
    if not text or text[-1] not in ')]':
        return False
    close = text[-1]
    opening = '(' if close == ')' else '['
    depth = 0
    for i in range(len(text) - 1, -1, -1):
        if text[i] == close:
            depth += 1
        elif text[i] == opening:
            depth -= 1
            if depth == 0:
                before = text[i - 1] if i else ' '
                return before.isascii() and (
                    before.isalnum() or before in '_$)]>'
                )
    return False


def predict(token, history):
    if not history and token in '0123456789' and len(token) == 1:
        return 0.35
    if token == '··':
        return 1.27
    if history == '1' and token == '2':
        return 4.27
    if token == '?.':
        return -0.5
    if token == '.out':  # the Java-style output-stream member
        return -1.28
    if token in ("['", '["'):
        return 0.17

    # Whitespace after a final dot generally signals the end of a sentence.
    if token.endswith(('\n', '\r', ' ')):
        return 0.0
    t = token.lstrip()
    if not (t.endswith(('.', '->', '::')) and len(t) < 12):
        return 0.002
    code = code_context(history)
    # Source listings may put a line number before an indented chain.
    normalized = history.replace('\\n', '\n').replace('\\r', '\r')
    normalized = normalized.replace('\\t', '\t')
    line_start = re.search(r'\n[ \t]*(?:\d+\t[ \t]*)?$', normalized)
    left = re.sub(r'\n[ \t]*\d+\t[ \t]*$', '', normalized).rstrip()
    if t.endswith('->'):
        if '--' in t:
            return 0.0
        spaced = token[0].isspace() or (history and history[-1].isspace())
        if spaced:
            newline = re.search(r'(?:\n|\\n)[ \t]*$', history)
            if code and '$' in history and newline and closes_access(left):
                return -1.6
            return 0.0
        if t != '->':
            return -2.05 if ')' in t else -0.85
        if not history or history[-1].isspace():
            return 0.0
        if re.search(r'\$this$', left):
            return -0.58
        if re.search(r'\$[A-Za-z_]\w*$', left):
            return -1.33
        if re.search(r'\$[A-Za-z_]\w*(?:->\w+)+$', left):
            return -1.45
        return -0.38 if code else -0.12
    if t.endswith('::'):
        if t.count(':') != 2 or token[0].isspace():
            return 0.0
        word = re.search(r'[A-Za-z_]\w*$', left)
        word = word.group() if word else ''
        if word == 'std':
            return -0.03
        if t.startswith('>'):
            return -0.63
        if code and word[:1].isupper():
            return -1.1 if '$' in history else -0.75
        return -0.4 if code else -0.18
    if _CLOSERS.fullmatch(t):
        if '()' in t:
            return -1.12 if t.endswith('].') else -2.28
        access = closes_access(history + t[:-1])
        quoted = any(c in t for c in "'\"")
        if code and t.endswith(("'.", '\".')):
            return -1.0
        if access and (code or quoted):
            if t.endswith('].'):
                return -2.4 if quoted else -1.72
            if t.count(')') >= 2:
                return -1.6
            return -2.4 if quoted else -2.1
        return 0.075
    if t == '.':
        if closes_access(left) and code:
            return -2.0 if token.startswith(' ') else -1.65
        if line_start and left.endswith((')', ']')):
            if not _MATH.search(history):
                return -1.5
        if token.startswith(' ') and code:
            if re.search(r'(?:[ \t]{2,}|\n[ \t]*)$', history.replace('\\n', '\n')):
                return -1.05
            return -0.5
    return 0.002


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = predict(token, history)
    return (document, (history + token)[-256:]), value

"""Approximate structural-boundary responses, especially date-field endings.

Month/day separators receive large negative values. Smaller rules cover
comma-grouped digit triplets, blanks in double-spaced reference-label prose,
line-initial imports, a Title heading's colon, and middle-dot leaders.
These are fitted typical responses, not an exact account of contextual strength.
The last 400 characters provide context; document changes clear that memory.
"""
import calendar
import re
import unicodedata

READS = ()
# Common European month names, in addition to English's standard calendar.
MONTHS = set(x.lower() for x in tuple(calendar.month_name)[1:]
             + tuple(calendar.month_abbr)[1:])
MONTHS.update('''janvier fevrier mars avril mai juin juillet aout septembre
    octobre novembre decembre janeiro fevereiro marco abril maio junho julho
    agosto setembro outubro novembro dezembro enero febrero marzo mayo junio
    julio septiembre octubre noviembre diciembre gennaio
    febbraio aprile maggio giugno luglio settembre ottobre novembre dicembre
    janv fevr sept dez setiembre abr ene januar februar marz juni juli
    oktober dezember januari februari maart
    april mei augustus oktober december marts
    января февраля марта апреля мая июня июля августа сентября октября
    ноября декабря'''.split())
DAY_END = re.compile(
    r'(?<!\d)\d{1,2}(?:st|nd|rd|th|er|\.)? +(?:(?:of|de) +)?$', re.I)

# Strip accents only for matching the month vocabulary.

def plain(s):
    if s.isascii():
        return s.lower()
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if not unicodedata.combining(c))


def ending_month(text):
    end = len(text) - int(text.endswith('.'))
    start = end
    while start and text[start - 1].isalpha():
        start -= 1
    word = text[start:end]
    if word and plain(word) in MONTHS:
        return text[:start], word
    return None


def response(before, token):
    before = before.replace('\\n', '\n')
    text = before + token
    if token == ' ' or token in (',', " '"):
        month_context = before[:-3] if before.endswith(' de') else before
        m = ending_month(month_context)
        # Month-day punctuation: May 27, or May 27 '21.
        md = re.search(r'([^\W\d_]+)\.?[ \xa0]+\d{1,2}(?:st|nd|rd|th)?([,.]?)$',
                       before[-40:], re.I)
        if md and plain(md[1]) in MONTHS:
            if token == ',':
                return -1.634
            if token == " '":
                return -3.816
            return -2.267 if md[2] == ',' else -1.745
        if token == ' ':
            if m:
                if DAY_END.search(m[0]):
                    return -1.917
                return 0.074
            # Numbered labels with generous spacing, as in patent figures.
            if re.search(r' {2}\d+[a-z]?(?= {2}| [,.])', before[-400:]):
                if before.endswith(' '):
                    return 0.053
                return -0.656
            return -0.01
    # The second separator in a numeric date, or a month-year separator.
    if token in ('/', '.', '-'):
        m = ending_month(before)
        if m and re.search(r'(?<!\d)\d{1,2}[- ]$', m[0]):
            return -0.54
        m = re.search(r'(?<!\d)(\d{1,4})([/.\-])(\d{1,2})$', before)
        if m and token == m[2]:
            if len(m[1]) == 4 and 1000 <= int(m[1]) <= 2100:
                return {'/': -0.555, '.': -0.180, '-': -0.188}[token]
            if 1 <= int(m[1]) <= 31 and 1 <= int(m[3]) <= 31:
                if token == '.' and (len(m[1]) != 2 or len(m[3]) != 2
                                     or int(m[3]) > 12):
                    return -0.002
                return {'/': -1.886, '.': -0.576, '-': -0.318}[token]
    # Completion of a three-digit group, such as the final zero in 5,000.
    if len(token) == 1 and token.isdigit():
        if re.search(r'\d,\d{3}$', text[-12:]):
            return -0.664
        if re.search(r'\d[ \xa0]\d{3}$', text[-12:]):
            return -0.082
        return -0.005
    if token.strip() in ('import', 'from', 'using', 'use'):
        line = before.rsplit('\n', 1)[-1]
        numbered = re.fullmatch(r'[ \t]*\d+[ \t]*', line)
        if numbered:
            return -0.414
        if not line.strip():
            word = token.strip()
            if word == 'import':
                if ';' in before[-160:]:
                    return -1.725 if '\r\n' in before else -1.981
                return -0.01
            return {'using': -0.951, 'use': -0.426, 'from': -0.506}[word]
    # A month immediately after a day: 23rd April or 24. Mai.
    if token.strip() and token.strip()[-1].isalpha():
        m = ending_month(text)
        if m and DAY_END.search(m[0]):
            return -1.598 if len(m[1]) > 3 else -0.971
    if token == ':' and re.search(r'(?:^|[>\n])Title$', before):
        return -0.945
    if token == 'de' or token == ' de':
        m = ending_month(before.rstrip())
        if m:
            return -1.338
    if token and set(token) == {'·'} and before.endswith('·'):
        return 1.182
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(before, token)
    return (doc, (before + token)[-400:]), value

"""Mostly a document-start response, sensitive to writing system and syntax.

Predict an onset value, usually negative, until a different token appears.
Greek writing and initial indentation give especially large negative pulses.
After varied text, the approximation is near zero except for Greek vowels,
the first blank after a real or escaped newline, and a forum's 'Joined:' field.
These are class averages, not exact predictions of individual lexical tokens.
"""
import unicodedata
from functools import lru_cache
import regex

READS = ()

PREPOSITIONS = set('of in on at by for with from to into onto under over '
                   'between through about after before'.split())
PRONOUNS = set('i you he she it we they me him her us them this that '
               'these those'.split())
QUESTIONS = set('what why how when where who which'.split())
CONDITIONALS = set('if unless while'.split())
CONJUNCTIONS = set('and or but as than because whether'.split())
AUXILIARIES = set('is are was were be been being do does did have has had '
                  'can could will would shall should may might must'.split())


def greek_text(s):
    return bool(regex.fullmatch(r'\p{Script=Greek}+', s))


@lru_cache(maxsize=8192)
def at_start(s):
    z = s.strip()
    low = z.lower()
    spaced = s.startswith(' ')
    if s.isspace():
        if '\n' in s or '\r' in s:
            return -0.3 if spaced else 0.4
        if s == '\t':
            return 0.21
        if s == ' ':
            return -1.44
        return -4.27 if s == '  ' else -5.9
    if s == '<|endoftext|>':
        return 6.03
    if s.startswith('<|'):
        return -1.0
