        return -3.4
    if z and all(c == '"' for c in z) and len(z) >= 3:
        return 6.5 if '\n' in s else 3.4
    if not any(c.isalnum() for c in z):
        if '\n' in s:
            return 0.1
        if z == ',':
            return -2.22
        if z == '.':
            return -1.21
        return -1.5
    if low == 'the':
        return (-3.1 if z.istitle() else -3.6) if spaced else -4.5
    if low == 'a':
        return (0.9 if z.istitle() else -0.3) if spaced else (
            -1.37 if z.istitle() else 0.3)
    if low == 'an':
        return -1.4 if spaced else -3.1
    if low in QUESTIONS:
        return -2.6 if spaced else -5.5
    if low in CONDITIONALS:
        return -2.9 if spaced else -5.6
    if low in PREPOSITIONS:
        if spaced:
            return -0.9 if z.istitle() else -1.9
        return -2.5 if z.istitle() else -1.25
    if low in AUXILIARIES:
        return -1.9
    if low in CONJUNCTIONS:
        return -1.5 if spaced else -2.7
    if low in PRONOUNS:
        if spaced:
            return -0.1 if z.istitle() else -0.8
        return -1.65 if z.istitle() else -0.7
    if z.isalpha():
        if spaced:
            return -0.85
        if z.istitle():
            return -1.75
        return -0.8 if z.isupper() else -1.25
    return -1.5


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, s, True, '')
    _, initial, unvaried, tail = carry
