"""layers.1.mlp.down_proj:3990, a document-start detector.

This component is almost silent except on the first token of each document (or of each
packed row): there it writes a large value that depends on what that token is, and it is
near zero everywhere else. At a document start the model has no earlier context, so the
value is set by the token alone. The program reads the token's script and shape:

  * unprintable control characters and rare scripts (Greek, Armenian, Georgian, Indic,
    Ethiopic, mathematical alphanumerics, ...) push the value strongly negative;
  * question words and common English function words are negative, more so without a
    leading space (a word opening a document) than with one;
  * other Latin words and punctuation are mildly negative;
  * CJK characters, digits and newlines sit near zero or slightly positive.

Everywhere else it predicts 0.
"""

import unicodedata

READS = ()

QUESTION_WORDS = set("what when where who why how which whose".split())
FUNCTION_WORDS = set(
    "the of to in is and a that with on as be for it are or by was this from at an "
    "which not has have they he we you i his her its their there these those".split()
)
RARE_SCRIPTS = {
    "GREEK", "ARMENIAN", "GEORGIAN", "MATHEMATICAL", "BENGALI", "DEVANAGARI", "MALAYALAM",
    "TAMIL", "MYANMAR", "SYRIAC", "LAO", "ETHIOPIC", "TIBETAN", "KHMER", "MONGOLIAN", "NKO",
}


def script_of(text):
    """The Unicode script name of the first letter-like character, e.g. 'LATIN'."""
    for ch in text:
        if ch.isspace():
            continue
        try:
            return unicodedata.name(ch).split()[0]
        except ValueError:
            return "UNNAMED"
    return "BLANK"


def start_value(text):
    """The component's value for a token that opens a document, from the token's text."""
    core = text.strip()
    script = script_of(text)
    if script == "UNNAMED":
        return -25.0
    if script in RARE_SCRIPTS:
        return -16.0
    if script == "BLANK":
        return -2.0 if "\n" not in text else 0.5
    if script == "CJK":
        return 0.4
    if script == "DIGIT" or core[:1].isdigit():
        return -0.6
    if script == "LATIN" and core.isalpha():
        word = core.lower()
        spaced = text.startswith(" ")
        if word in QUESTION_WORDS:
            return -2.6 if spaced else -5.0
        if word in FUNCTION_WORDS:
            return -1.8 if spaced else -2.8
        return -1.2
    return -1.7


def step(carry, prefix, upstream):
    """Predict the value at this position: nonzero only where a document begins."""
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if not starts_document:
        return None, 0.0
    return None, float(start_value(prefix.token_strings[t]))

