    doc = prefix.document_ids[-1]
    previous, dutch = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    dutch = min(8, dutch + (word in DUTCH_CUES))
    last = previous[-1:].lower()
    unspaced = bool(previous) and not token[:1].isspace()
    value = 0.0

    if word.lstrip('-') == 'na':
        if not previous:
            value = -0.2
        elif unspaced:
            value = 3.0 if last in 'ndts' else 0.8
            if token.isupper():
                value = 1.3 if last.isalpha() else 0.3
            if previous.lower().endswith('ij'):
                value = 4.0
        else:
            value = 0.15
    elif word == 'на':
        value = 0.8 if unspaced and last in 'нгсш' else 0.05
    elif word == 'ナ':
        value = 0.2
    elif word == 'anna':
        value = 2.2 if unspaced and token[:1].islower() else 0.4
    elif word == 'rna':
        value = 0.6 if unspaced else 0.0
    elif unspaced and token in {'a', 'A', 'As'} and last == 'n':
        value = 0.6
    elif unspaced and last == 'e':
        if word == 'ith':
            value = 2.0
        elif word == 'ige':
            value = 0.7

    # Gate Dutch motion and temporal-following forms with function-word evidence.
    if dutch >= 3:
        if word in {'ga', 'gaan', 'gaat', 'na'}:
