READS = ()

# Preceding line type: (value on Joined, value on its colon).
JOINED = {
    'blank': (0.0, -1.2),
    'number': (-0.45, -4.6),
    'description': (-1.8, -8.7),
    'rank': (-3.7, -12.5),
    'Intern': (-5.1, -10.6),
    'Manager': (-5.1, -17.5),
    'Senior Manager': (-6.3, -14.7),
    'Director': (-6.7, -15.7),
    'Member': (-0.5, -3.3),
    'missing': (-0.4, -5.0),
