def joined_kind(before):
    """What sort of line precedes a forum's Joined field?"""
    if before.endswith('\n\n') or before.endswith('\r\n\r\n'):
        return 'blank'
    line = before.rstrip('\r\n').rsplit('\n', 1)[-1].strip()
    if not line:
        return 'missing'
    if line in ('Intern', 'Manager', 'Senior Manager', 'Director', 'Member'):
