    if newline and s == 'Status':
        return -7.2 if single else 0.0
    if (newline or line.strip() == '•') and s.strip() == 'Location':
        return -4.2 if profile else 0.0
    if newline and s == 'Intern':
        return -7.1
    if newline and s == 'Director':
        return -4.3
    if newline and s == 'Manager':
        return -6.3 if single else -7.0
    if s == ' Manager' and line == 'Senior':
        return -10.0
    if single and s == 'CEO':
        return -2.8
    if s == '\n' and prev == 'Intern':
        return -2.3

