"""Layer-1 MLP down-projection, component 3996: a "code, markup and escape symbols" detector.

What it responds to, in plain terms. Ordinary words, digits and prose punctuation (. , : ) ;)
give almost nothing. The component rises on:
  - escape codes: a backslash joined to what follows (\\n, \\", \\\\), and the token right
    after a backslash (LaTeX \\left, \\phantom, \\quad); a lone backslash is weaker;
  - the tag name after an HTML/XML bracket (<span, </div>);
  - chat and document boundary markers (<|endoftext|>, <|im_end|>, </think>);
  - indentation: tab runs, and runs of spaces (or newline plus spaces), stronger when deeper;
  - decorative or code symbols, most when they follow a space (" |", " [", " @", " //"),
    repeated runs (// == ---- || ``, ...), and odd characters (no-break space, NUL);
    quotes count only after a space;
  - it stays low on symbols that close a line (");" or "{" before a newline).
It is negative on the first token of each document, where the context restarts.

The values are hand-set, rounded means read off the activations, not fitted weights.
"""

READS = ()

MARKERS = ("<|endoftext|>", "<|im_end|>", "</think>")
SYMBOLS = set("|[]{}#$*<>@&~^…✓✗•")
QUOTES = set("\"'`“”«»")
RUNS = set("=-#|[{~^>_*/`.")


def whitespace(token):
    n = len(token)
    if "\t" in token:
        return min(1.7, 0.5 + 0.2 * n)
    if "\n" in token or "\r" in token:
        if n == 1:
            return 0.0
        return 0.2 if token.strip("\r\n") == "" else min(2.0, 0.2 * n)
    return 0.0 if n == 1 else (0.45 if n <= 3 else 1.2)


def symbol(token):
    space = token[0] == " "
    if "\x00" in token:
        return 3.0
    if "\xa0" in token:
        return 1.2
    if "�" in token:
        return 0.5
    if "\n" in token or ":" in token:
        return 0.0
    if any(token.count(c) >= 2 for c in RUNS if c in token):
        return 1.5
    if any(c in QUOTES for c in token):
        return 1.0 if space else 0.2
    if any(c in SYMBOLS for c in token):
        return 1.0 if space else 0.7
    return 0.2 if space else 0.0


def value(token, prev):
    if token in MARKERS:
        return 2.0
    if "\\" in token:
        if token.count("\\") == 1 and token.endswith("\\"):
            return 1.0 if token == "\\" else 0.7
        return 2.2
    if "\\" in prev:
        return 1.4
    if prev.endswith("<") or prev.endswith("</"):
        return 1.3 if token.isalpha() else 0.0
    if token.strip() == "" and token != "\xa0":
        return whitespace(token)
