"""An opening-token pulse, sustained while that opening token repeats.

Its size is approximated by visible token properties, not a vocabulary lookup.
Whitespace, digits and sentence punctuation have smaller opening pulses than
words; word length, case and a preceding space refine the word estimate.
Outside the opening run the predicted contribution is zero. Token-specific
exceptions and small contextual fluctuations are deliberately omitted.
"""
from wordfreq import zipf_frequency

READS = ()
SENTENCE_PUNCTUATION = frozenset('.,:;!?()[]{}，。；：！？（）【】')


def opening_strength(token):
    word = token.strip()
    if token.startswith('<|') or token.startswith('</tool_'):
        return 12.0
