        return 6.0
    if '\ufffd' in token:
        return 9.0
    if not any(c.isalpha() for c in word):
        if len(word) > 1 and len(set(word)) == 1:
            return 18.0
        if word and all(c in SENTENCE_PUNCTUATION for c in word):
            return 4.3
        return 8.0
    value = 10.8 + 0.36 * min(len(word), 12)
    value += 1.6 * word[:1].isupper() - 1.1 * word.isupper()
    if token[:1].isspace():
        frequency = zipf_frequency(word.lower(), 'en') if word.isalpha() else 0
        value -= 1.9 + 0.4 * frequency
    if not token.isascii():
        value -= 1.8
    if not word.isalpha():
        value -= 0.9
