def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != document:
        carry = (document, token, opening_strength(prefix.token_strings[-1]), True)
    else:
        doc, opening, value, active = carry
        carry = (doc, opening, value, active and token == opening)
    return carry, carry[2] if carry[3] else 0.0

"""A surface-grammar approximation to question and complement-clause cues.

The strongest signal is negative: 'if' after checking, knowing or uncertainty,
not an ordinary conditional. Other clause introducers have smaller responses.
WordNet handles English verb inflection. A short byte suffix preserves preceding
words and split Unicode characters; it is cleared at document boundaries.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
CHECK = set('check see test verify determine detect assess evaluate ascertain '
            'establish investigate examine understand'.split())
KNOW = set('know tell wonder'.split())
UNCERTAIN = set('sure unsure certain uncertain doubtful unclear clear'.split())
ASK = set('ask decide doubt care matter depend say indicate discuss worry '
          'gauge mean explain consider'.split())
ASSERT = set('say think believe assume suppose conclude mean show indicate '
             'demonstrate state report argue claim assert agree feel hope '
             'require ensure'.split())
VERIFY = set('check verify confirm test prove'.split())
PROOF = set('evidence proof probability likelihood chance risk'.split())
# Multilingual complementizers and question markers, not token IDs.
CLAUSES = {
    'om': -3.1, 'att': -1.5, 'czy': -4.2, 'aby': -2.1,
    'że': -1.6, 'že': -0.7, 'să': -1.5, 'hogy': -0.4,
    'que': -0.7, 'qu': -0.6, 'che': -0.6,
    'dass': -0.8, 'daß': -0.9, 'dafs': -0.9, 'dat': -0.4,
    'si': -0.9, 'se': -0.4, 'ob': -0.8, 'αν': -5.8,
    'أن': -2.9, 'ان': -2.9, 'إن': -2.4, 'هل': -2.7, 'إذا': -2.8,
    'بأن': -3.7, 'وأن': -2.2, 'لأن': -1.5,
    'dacă': -2.7, 'daca': -2.7,
    'selvom': -3.8, 'dersom': -5.0, 'ettersom': -5.0,
}
ROMANCE_KNOW = set('saber sabe sabes savoir sais sait sepas sapere sa '
                   'vedere predecir'.split())
WORD = re.compile(r'([^\W\d_]+)$')
TRIGGERS = set(CLAUSES) | set(('if whether that how why maybe perhaps '
    'is are do does did can will not though come like mean makes evidence').split())

@lru_cache(maxsize=8192)
def bases(word):
    return set(wordnet.base_forms(word)) | {word}


def predict(text, raw):
    # Thai complementizer 'that' (excluding comparative กว่า), and causative ให้.
    if raw.endswith('่า') and text.endswith('ว่า') and not text.endswith('กว่า'):
        return -3.5
    if raw == 'ให' or (raw == '้' and text.endswith('ให้')):
        return -2.7
    m = WORD.search(text)
    if not m:
        return 0.0
    spelled = m[1]
    word = spelled.lower()
    if word not in TRIGGERS:
        return 0.0
    before = text[:m.start()].rstrip()
    previous = WORD.search(before)
    prev = previous[1].lower() if previous else ''
    root = bases(prev)
    if word == 'if':
        if spelled != 'if':
            return -0.43
        if root & CHECK:
            return -6.4
        if root & KNOW:
            negative = prev in {'know', 'knowing', 'known'} and re.search(
                r"\bnot\b|n['’]t\b|\bnever\b", before[-25:])
            return -9.0 if negative else -6.3
        if root & UNCERTAIN:
            return -7.3
        if root & ASK:
            return -4.0
        if prev in {'me', 'you', 'us', 'them', 'him', 'her'}:
            m2 = WORD.search(before[:previous.start()].rstrip())
            if m2 and bases(m2[1].lower()) & (KNOW | ASK):
                return -4.0
        if re.search(r'\b(find|found|figure|figured) out$|\bdepending on$', before):
            return -5.6
        if prev in {'as', 'or'}:
            return -2.4 if prev == 'as' else -2.0
        if prev in {'only', 'even', 'and', 'what', 'especially'}:
            return -0.9
        return -0.43 if raw[:1].isspace() else -0.3
    if word == 'whether':
        if root & (CHECK | KNOW | UNCERTAIN | {'ask', 'decide'}):
            return -4.4
        if prev in {'of', 'on', 'about', 'to'}:
            return -4.6
        return -1.5 if spelled[0].isupper() or before[-1:] in '.,:?!' else -3.1
    if word == 'that':
        if root & PROOF:
            return -1.6
        if root & VERIFY:
            return -1.3
        if root & CHECK:
            return -0.3
        if root & UNCERTAIN:
            return -0.9
        if root & ASSERT:
            return -0.64
        if prev in {'and', 'or', 'not'}:
            return -0.82
        return -0.27 if spelled[0].isupper() else -0.14
    if word in {'how', 'why'}:
        return (-0.23 if word == 'how' else -0.05) if spelled[0].isupper() else (
            -0.55 if word == 'how' else -0.58)
    if word in {'maybe', 'perhaps'}:
        return -0.4 if word == 'maybe' else -0.35
    if spelled in {'Do', 'Can', 'Did', 'Is', 'Are', 'Does', 'Will'}:
        return -0.4 if spelled in {'Do', 'Can'} else -0.7
    if word in {'is', 'are', 'do', 'does', 'did', 'can', 'will'}:
        if prev in {'how', 'why'}:
            return -0.7
        return -0.14 if word in {'do', 'does'} else 0.0
    if word == 'not' and re.search(r'\bwhether or$', before, re.I):
        return -3.5
    if word == 'though' and prev == 'as':
        return -2.7
    if word == 'come' and prev == 'how':
        return -4.2
    if word == 'like' and root & {'act', 'feel', 'look', 'seem'}:
        return -3.0 if root & {'act', 'feel'} else -2.0
    if word == 'mean' and re.search(r'\bdoes that$', before, re.I):
        return -2.4
    if (word == 'makes' and prev == 'what') or (word == 'evidence' and prev == 'no'):
        return -2.2
    if word == 'ob' and (prev in {'als', 'egal'} or re.search(r'Frage,?$', before)):
        return -5.0
    if word in {'si', 'se'}:
        if prev in ROMANCE_KNOW:
            return -6.5
        if prev in {'même', 'como', 'comme'}:
            return -3.5
    if word in {'que', 'qu'}:
        if prev in {'para', 'de', 'por', 'comme'}:
            return {'para': -4.0, 'de': -2.45, 'por': -3.7, 'comme': -5.0}[prev]
    if word in {'om', 'att', 'si', 'se', 'qu', 'que', 'che', 'ob'}:
        if spelled != word or not raw[:1].isspace():
            return 0.0
    if word == 'czy' and spelled.isupper():
        return 0.0
    return CLAUSES.get(word, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    text = (tail + raw).decode('utf-8', errors='replace')
    value = predict(text, raw.decode('utf-8', errors='replace'))
    return (doc, (tail + raw)[-384:]), value

programs.haiku:
"""Clause-opener detector: a negative response on the word that opens an embedded
question or clause of doubt, belief or hypothesis. Strongest for "if"/"whether" after
verbs of checking or doubt ("check if", "not sure whether"), weaker for "that" after
verbs of belief or evidence, and for "how"/"why" and foreign-language equivalents.
Everything else, including ordinary conditional "if" after punctuation, is near 0."""
READS = ()

# Verbs and adjectives that govern an indirect question: "check if", "unsure whether".
ASK = {"check", "checks", "checking", "checked", "see", "know", "knows", "knowing", "sure",
       "unsure", "wonder", "wondering", "wonders", "wondered", "determine", "determining",
       "determines", "test", "testing", "examine", "ask", "asks", "asked", "asking", "tell",
       "matter", "doubt", "doubts", "doubtful", "decide", "establish", "verify", "understand",
       "consider", "considering", "investigate", "find", "figure", "discover", "explore",
       "clear", "unclear", "question", "depending", "depends", "depend", "care", "cares",
       "indicate", "indicates", "learn", "remember", "realize", "reveal", "guess",
       "saber", "sapere", "vedere", "sehen", "prüfen", "wissen"}
# Verbs, nouns and adjectives that take a that-clause of belief or evidence.
BELIEF = {"think", "say", "saying", "believe", "assume", "assuming", "suppose", "show", "shown",
          "showed", "demonstrate", "demonstrated", "mean", "confirm", "confirming", "verify",
          "verifies", "check", "doubt", "deny", "assert", "asserts", "establish", "evidence",
          "proof", "prove", "claim", "claims", "argue", "feel", "hope", "indicates", "indicate",
          "suggests", "suggest", "ensure", "guarantee", "chance", "probability", "likely",
          "unlikely", "probable", "sure", "imply", "implies", "conclude", "concluded", "means",
          "shows", "requires", "notice", "wonder", "not"}
# Verbs after which "like" or "though" opens a clause ("feel like", "act as though").
SEEM = {"feel", "feels", "feeling", "felt", "act", "acts", "acting", "look", "looks", "seem",
        "seems", "sound", "sounds", "as"}
CONJ = {"and", "but", "or", "even", "only", "then", "so", "what", "as", "not", "also", "nor"}
# "that" and "whether" in other languages: strong for Arabic أن/إن/ان, Polish czy, Swedish om.
FOREIGN_STRONG = {"أن", "إن", "ان", "czy", "om"}
QUESTION_AUX = {"Is", "Are", "Does", "Do", "Did", "Will", "Would", "Can", "Could", "Should",
                "Was", "Has", "Have"}
FOREIGN = {"que", "qu", "si", "ob", "daß", "dass", "che", "att", "wenn", "hogy", "se", "ли",
           "aby", "że", "ze", "že", "să", "sä", "dat", "zy"}


def category(prefix):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev_raw = prefix.token_strings[-2] if len(prefix) > 1 else ""
    prev = prev_raw.strip().lower()
    punct_prev = not any(ch.isalpha() for ch in prev)
    if word in ("if", "whether"):
        if not raw.startswith(" ") and word == "if":
            return "joined_if"          # "if" inside a word, as in "Ka|if|eng"
        if word == "whether":
            return "whether_punct" if punct_prev else "whether"
        if prev == "else":
            return "else_if"            # code: "else if (...)"
        if prev in ASK:
            return "ask_if"
        if prev in SEEM:
            return "seem_if"
        if prev in CONJ:
            return "conj_if"
        return "word_if" if not punct_prev else "punct_if"
    if word == "that":
        return "that_belief" if prev in BELIEF else "that_other"
    if word in ("like", "though"):
        return word + ("_seem" if prev in SEEM else "_other")
    if word in ("how", "why", "maybe", "perhaps"):
        return "wh"
    if word in FOREIGN_STRONG and raw.startswith(" "):
        return "foreign_strong"
    if word == "ν" and prev == "α":
        return "greek_an"               # Greek "αν" (if), split into two tokens
    if raw.strip() == "ว่า":
        return "thai_wa"                # Thai "ว่า" (that)
    if raw.strip() in QUESTION_AUX and punct_prev:
        return "question_aux"           # sentence-initial "Is", "Does", "Will": yes/no question
    if word in FOREIGN and raw.startswith(" "):
        return "foreign"
    return "none"


VALUE = {
    "ask_if": -6.2,         # "check if", "not sure if", "ask if": an indirect yes/no question
    "whether": -3.7,        # "whether" after a word
    "whether_punct": -1.5,  # sentence-initial "Whether"
    "seem_if": -2.5,        # "as if", "feel if"
    "conj_if": -0.9,        # "and if", "even if", "or if"
    "word_if": -1.0,        # "...edit it again if necessary": a conditional
    "punct_if": -0.3,       # ". If you ..." and ", if ..."
    "else_if": 0.0,         # code: "else if"
    "joined_if": 0.0,       # "if" inside a word
    "that_belief": -0.8,    # "think that", "assume that", "confirm that"
    "that_other": -0.2,     # any other "that"
    "like_seem": -1.3,      # "feel like"
    "like_other": 0.0,
    "though_seem": -1.4,    # "as though"
    "though_other": 0.0,
    "wh": -0.5,             # "how", "why", "maybe", "perhaps"
    "foreign": -0.7,        # que, si, ob, dass, wenn, se, ... (that/if in other languages)
    "foreign_strong": -3.0, # أن, إن, czy, om
    "greek_an": -3.4,       # Greek "αν" (if), split into two tokens
    "thai_wa": -2.2,        # Thai "ว่า" (that)
    "question_aux": -0.6,   # sentence-initial "Is", "Does", "Will": a yes/no question
    "none": 0.0,
}


def step(carry, prefix, upstream):
    return carry, float(VALUE[category(prefix)])

programs.sol:
"""A spelling-sensitive approximation of the component's largest lexical spikes.

Earth/地球 and arth are strongly positive; Arthur, Clark, clay and some
split th spellings are weaker positives. Romance aquel/quell/cel spellings
and qu/aqu continuations are negative, especially completed aquel forms.
These are token/chunk rules, not a general semantic Earth detector: e.g.
whole earthquake and arthritis tokens get zero. Weak background activity
is omitted. Only the previous token and current Latin word are carried,
with state reset at document boundaries.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, word = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    s = token.strip()
    low = s.lower()
    p = previous.lower()
    attached = bool(token and token[0].isalpha() and previous[-1:].isalpha())
    newword = re.split('[^a-zA-Z]', word + token)[-1].lower()[-32:]
    value = 0.0
    if low == 'earth':
        value = 4.8 if s[0].isupper() else 3.7
    elif low == '-earth':
        value = 4.5
    elif low == 'arth':
        value = 4.2
    elif low == 'arthur':
        value = 3.0 if token == s else 1.7
    elif low == 'clark':
        value = 2.2
    elif low == 'clay':
        value = 1.4
    elif low == '地球':
        value = 5.0
    elif attached and low == 'th' and p.endswith('r'):
        value = 2.6
    elif attached and low == 'th' and p.endswith(('w', 'y')):
        value = 1.8
    elif attached and low in ('then', 'thing') and p.endswith('ear'):
        value = 3.0
    elif attached and word == 'earth' and low == 'y':
        value = 3.0
    elif re.match(r'^[dn]?aquel', newword) and len(token) > 1:
        if re.match(r'^[dn]?aquel', word):
            value = -5.0
        else:
            value = -8.5 if attached else -6.0
    elif re.fullmatch(r'quell[oaie]|quel|celui|celles?', newword):
        value = -1.7
    elif attached and word in ('cual', 'qual', 'quel') and low.startswith('qu'):
        value = -4.0
    elif low in ('aqu', 'aque'):
        value = -1.0
    elif attached and p.strip() in ('aqu', 'aque'):
        value = -1.3
    elif attached and p.strip() == 'que':
        value = -1.0
    elif attached and p.strip() == 'qu':
        value = -0.7 if low.startswith('e') else -0.35
    return (doc, token, newword), value

programs.haiku:
"""Component layers.1.mlp.down_proj:4000, a spelling detector for "earth".

It reads the text so far and the word the current token belongs to, and predicts:
* strongly positive when the text now ends in "earth" or "arth" (Earth, earth, hearth,
  Carthage): the spike this component is known for; weaker for the name Arthur;
* negative on Romance "that/which" words: "aquel" (most negative), and words starting
  with "quel" (quel, quella, quelle, quello) or "aqu" (aqui, aqueous);
* zero everywhere else.

It captures the large spikes; the component's many small, scattered values are not modelled.
"""

READS = ()

# (ending of the text so far, predicted activation); the first match wins
ENDINGS = (
    ("earth", 4.0),
    ("arth", 4.0),
    ("arthur", 2.0),
)

# (start of the current word, predicted activation); the first match wins
ROMANCE_THAT = (
    ("aquel", -6.0),
    ("quel", -2.5),
    ("aqu", -1.0),
)


def current_word(prefix):
    """Lowercase letters of the word ending at the current token, within its document."""
    doc = prefix.document_ids[-1]
    parts = []
    for i in range(len(prefix.token_strings) - 1, -1, -1):
        if prefix.document_ids[i] != doc:
            break
        text = prefix.token_strings[i]
        letters = text.lstrip(" ")
        if not letters or not letters.isalpha():
            break
        parts.append(letters.lower())
        if text.startswith(" "):
            break
    return "".join(reversed(parts))


def step(carry, prefix, upstream):
    # carry: the last few lowercase characters of the current document's text
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]
    tail = "" if carry is None or new_doc else carry
    tail = (tail + prefix.token_strings[-1].lower())[-12:]
    for ending, value in ENDINGS:
        if tail.endswith(ending):
            return tail, value
    word = current_word(prefix)
    for start, value in ROMANCE_THAT:
        if word.startswith(start):
            return tail, value
    return tail, 0.0

programs.sol:
"""A coarse predictor of sparse notation and document-opening responses.

Subscript markers, spaced LaTeX separators, primes and column padding depend
on the preceding symbol. Their short-context increment usually fades as the
document grows. Explicit opening syntax has separate fixed responses. Most
ordinary text is predicted near zero; many lexical spikes remain unexplained.
"""
import unicodedata

READS = ()
GREEK = set('alpha beta gamma delta epsilon zeta eta theta iota kappa lambda '
            'mu nu xi omicron pi rho sigma tau upsilon phi chi psi omega'.split())
RELATIONS = set('in subset supset subseteq supseteq le ge leq geq neq equiv '
                'sim approx to perp'.split())
OPENING_SYNTAX = {
    'def': 2.73,                 # Python function-definition keyword
    '**': 1.97,                 # Markdown bold delimiter / exponent notation
    '¿': 1.98,                  # Spanish opening question mark
    '{': 0.67, '_{': 0.75,     # opening mathematical braces
    '\r': -1.66,                # carriage return
    '\\n': -1.38, '\\t': -1.30,  # literal newline / tab escapes
    '··': 0.83,                 # repeated interpunct separator
}


def variable(text):
    text = text.strip().lstrip('({[|,;+-')
    return (text.lower() in GREEK or
            (len(text) == 1 and text.isalpha() and
             (text.isascii() or 'GREEK' in unicodedata.name(text, ''))))


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        start, first, repeated = prefix.position, s, True
    else:
        _, start, first, repeated = carry
        repeated = repeated and s == first
    position = prefix.position - start
    p = prefix.token_strings[-2] if position else ''
    st, pt = s.strip(), p.strip()
    short = 1 / (1 + position / 60)
    value = -0.0015
    if position == 0 or (repeated and s in OPENING_SYNTAX):
        value = OPENING_SYNTAX.get(s, 0.075 if st.isalpha() and st.isascii()
                                  else 0.19 if s.startswith('<|')
                                  else 0.17 if not s.isascii() else 0.03)
    elif position == 1 and p == 'Title' and s == ':':
        value = -2.435
    elif st == '_{' or (st == '{' and pt == '_'):
        value = -0.15
        if len(pt) == 1 and pt in 'abcd':
            value += 1.06 * short
        elif variable(p):
            value = 1.0 * short if position <= 8 else -0.08
    elif prefix.token_bytes[-1].endswith(b'\xe2\x82') and variable(p):
        # Shared UTF-8 lead bytes of subscripts and other symbols.
        value = -0.08 + 0.68 * short
    elif s == ' \\':
        value = -0.03
        if variable(p) or pt in RELATIONS:
            value = -0.11 + 0.40 * short
        elif pt and pt[-1].isdigit():
            value = -0.10 + 0.24 * short
    elif s == ' ,':
        previous = ''.join(prefix.token_strings[-3:-1]) if position >= 2 else p
        value = (1.99 if previous.endswith(('dots', '...')) else
                 0.125 + 0.96 * short if pt.lower() in GREEK else -0.03)
    elif st in ('′', '″'):
        value = (1.2 * short if variable(p) and position < 16
                 else -0.09 + 0.3 * short)
    elif st == '•' and pt and pt[-1].isdigit():
        value = -0.27 + 1.36 * short
    elif s == '    ':
        value = (0.70 if p == ' (' else
                 0.125 + 0.58 * short if '\ufffd' in p else -0.03)
    elif s == '\r':
        value = -0.08
    elif '\\' in s:
        value = -0.03
    return (doc, start, first, repeated), float(value)

"""Lexical responses: membership labels, page furniture, and word beginnings.

The main rule responds to singular 'member'. Capitalization and relation
separators raise its value; preceding group nouns reduce it. A few
page/citation labels have separate responses. Indonesian and Dutch context distinguishes word beginnings
such as Indonesian memberi- from the English noun 'member'. These are
surface-text rules, not a general semantic analysis of membership.
Unrecognized tokens stay near zero. Context is bounded to 256 characters
and resets at document changes and end-of-text markers.
"""

import re

READS = ()
INDONESIAN = re.compile(r'\b(yang|untuk|dengan|tidak|sudah|oleh)\b')
DUTCH = re.compile(r'\b(het|een|uw|niet|worden)\b')
GROUPS = set('family team board council staff cast committee group faculty'.split())
RELATION_SEPARATORS = {
    '|': 4.5,
    '—': 2.7,
    ',': 3.35,
    ':': 2.4,
    '•': 5.0,
}
# Indonesian word beginnings completed by this token, e.g. d + iper.
BEGINNINGS = {
    'diper': 10.0,
    'pemer': 10.2,
    'memper': 14.0,
    'diber': 6.0,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, text = '', ''
    else:
        _, previous, text = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    prev = previous.strip()
    value = 0.003

    if lower == 'member':
        value = 2.4 if word == 'Member' else 1.4
        if prev in RELATION_SEPARATORS:
            value = RELATION_SEPARATORS[prev]
        elif prev.lower() in GROUPS:
            value = 0.5
    elif lower == 'members':
        value = 0.3
    elif word == 'Article':
        value = 10.0 if prev.endswith('View') else -0.1
    elif word == 'article':
        value = -0.5 if prev == 'this' else -0.25
    elif word in {'Message', 'Comment'} and prev == 'Author':
        value = 3.0
    elif word == 'Issue' and prev == ',':
        value = -3.5
    elif word == 'Version' and text.endswith('Apache License,'):
        value = -1.0
    elif token == '\u0651':  # Arabic consonant-doubling mark, shadda.
        value = 0.55

    if lower in {'member', 'per', 'be'}:
        if INDONESIAN.search(text):
            if lower == 'member':
                value = 10.0
            elif token in {' per', ' Per'}:
                value = 3.0
            elif token == ' be':
                value = 3.7
        elif token == ' be' and DUTCH.search(text):
            value = 4.0

    if token and not token[0].isspace():
        beginning = (previous + token).strip().lower()
        value = BEGINNINGS.get(beginning, value)

    if token == '<|endoftext|>':
        return (doc, '', ''), value
    return (doc, token, (text + token)[-256:]), value

