What it responds to, in plain terms:

1. The English word "member" used as a membership: strongest where it opens a
   membership field in a structured list ("Name | member of sports team", "Name, member of
   ..."), a forum badge ("Member", "Gold Member") or follows "was a"; weak for "family member",
   "cast member", "staff member", and for plural "members".
2. Indonesian verbs and nouns built on per-, ber-, mem- and pe- prefixes, at the token where the
   prefix shows: memper- and mempe- (strongest), diper-, pemer- (as in "pemerintah") and diber-,
   then word-initial per- (perlu, permainan, perizinan), then pe-. Indonesian "member" as in
   "memberikan" fires as well. These only count once the document reads as Indonesian (two
   common Indonesian function words such as "yang", "dan", "untuk" seen so far in it), so
   the English "per", "person" and "period" stay at zero.
3. Two boilerplate cases: "Article" after "View" (PubMed / Google Scholar links), and the colon
   of "Title:". A comma followed by "Issue" in a journal citation is strongly negative.

Everything else predicts 0. The program is stateful only through a running count of
Indonesian function words in the current document, reset at each document boundary.
"""
READS = ()

INDO_STOP = set("yang dan untuk dengan tidak akan dalam oleh adalah ini itu tersebut sebagai "
                "secara telah saya kami kita mereka juga sudah bisa karena".split())
# (stem, activation) for the token at which a word first reaches the stem
INDO_STEMS = (("memper", 10.0), ("mempe", 10.0), ("diper", 9.0), ("pemer", 9.0), ("diber", 6.0),
              ("per", 2.8), ("pe", 1.5))
NOT_MEMBERSHIP = {" family", " cast", " staff", " team", " Team", " board", " Every", " every"}
LIST_BEFORE = {"|", ",", "—", "->", ":", "•", "\n", "Gold", "·"}


def _word(prefix):
    """The current word so far, lowercase: tokens back to the last one starting with a space."""
    s = prefix.token_strings
    k = len(s) - 1
    word = s[k]
    while (not word[:1].isspace() and k > 0 and s[k - 1].strip().isalpha()
           and prefix.document_ids[k - 1] == prefix.document_ids[k]):
        k -= 1
        word = s[k] + word
    return word.strip().lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "word": "", "stop": 0}
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    # count Indonesian function words seen so far in this document
    if tok[:1].isspace() or not carry["word"]:
        if carry["word"] in INDO_STOP:
            carry["stop"] += 1
        carry["word"] = tok.strip().lower()
    else:
        carry["word"] += tok.strip().lower()
    indonesian = carry["stop"] >= 2
    bare = tok.strip()

    if bare.lower() == "member":
        if prev.strip() in LIST_BEFORE or prev.endswith("\n"):
            return carry, 3.5
        if prev in NOT_MEMBERSHIP:
            return carry, 0.5
        if indonesian:
            return carry, 8.0
        return carry, 1.4
    if bare.lower() == "members":
        return carry, 0.3
    if bare == "Article" and prev.strip() == "View":
        return carry, 10.0
    if bare == "Issue" and prev == ",":
        return carry, -6.0
    if bare == ":" and prev == "Title":
        return carry, 4.3
    if indonesian:
        word = _word(prefix)
        prev_word = word[: len(word) - len(bare)]
        for stem, value in INDO_STEMS:
            if len(prev_word) < len(stem) <= len(word) and word.startswith(stem):
                return carry, value
    return carry, 0.0

programs.sol:
"""Detect Cyrillic раз-/рас-/роз- and Latin raz-/roz- spelling pieces.

The response is strongest when a piece finishes the prefix, and weaker
when the same token contains more of the word. Case and word boundaries
change its strength. A small secondary response marks GitHub .com links
and a negative response marks Java's `package com`. Repeated pairs
of middle dots are positive too. Other cases are left near zero.
"""
# Only these five letters are shared for matching; accents are not erased.
CYRILLIC_PREFIX_LETTERS = str.maketrans("разос", "razos")

VOWELS = frozenset('aeiouyаеёиоуыэюя')
# Russian words specifying how many times, or which occasion.
OCCASION_WORDS = {'этот', 'тот', 'каждый', 'один', 'еще', 'ещё',
                  'несколько', 'много'}
READS = ()


def spelling(text):
    return text.lower().translate(CYRILLIC_PREFIX_LETTERS)


def initial_value(text):
    if text.startswith('raz'):
        return 12.8 / (1 + 1.1 * (len(text) - 3))
    if text.startswith('roz'):
        return 12.0 / (1 + 1.1 * (len(text) - 3))
    if text.startswith('ras'):
        extra = len(text) - (4 if text.startswith('rass') else 3)
        return 7.8 / (1 + 0.35 * extra)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = older = ''
    else:
        _, previous, older = carry
    text = prefix.token_strings[-1]
    bare = text.lstrip()
    current = spelling(bare)
    prev = spelling(previous.strip())
    old = spelling(older.strip())
    value = 0.0
    if bare.isalpha():
        boundary = text != bare or not previous or not previous[-1:].isalpha()
        value = initial_value(current)
        if value:
            cyrillic = bare[0].lower() == 'р'
            if not cyrillic and current.startswith('ras'):
                value = 0.0
            elif not cyrillic and current.startswith('raz'):
                value *= 0.45
            value *= 1.28 if cyrillic and bare[0].isupper() else 1.0
            if not boundary:
                value *= 0.2
        # The r and the rest of the prefix may be in different tokens.
        if (text == bare and prev.endswith('r')
                and current.startswith(('az', 'oz', 'as'))
                and not (current.startswith('as') and bare.lower().startswith('a'))):
            stem = current[:2]
            base = 13.5 if stem == 'as' else 16.5
            if previous.strip() == 'Р':
                if stem == 'oz' and previous.startswith(' '):
                    base = 10.5
                elif stem == 'az':
                    base += 2
            extra = len(current) - 2
            if stem == 'as' and current.startswith('ass'):
                extra -= 1
            decay = 0.65 if stem == 'as' else 0.15
            if prev == 'r':
                strength = 1.0
            elif prev[-2] in VOWELS:
                strength = 0.5
            else:
                strength = 0.05
            if (prev == 'r' and previous == previous.lstrip()
                    and older[-1:].isalpha()):
                strength *= 0.15
            if stem == 'az' and bare.lower().startswith('a'):
                strength *= 0.5
            value = strength * base / (1 + decay * extra)
        elif text == bare and prev in ('ro', 'ra') and current.startswith('z'):
            base = 14.5
            value = base / (1 + 0.12 * (len(current) - 1))
        # A little of the response remains on a short following piece.
        elif (text == bare and prev in ('raz', 'ras', 'rass', 'roz')
              and len(current) <= 2):
            value = (4.5 if len(current) == 1 else 1.1)
            if prev in ('ras', 'rass'):
                value *= 0.25
        elif (text == bare and old == 'r' and prev in ('oz', 'az', 'as')
              and len(current) <= 2):
            value = (12.0 if prev == 'oz' else 3.0) / len(current)**0.8
    if bare == 'раз' and (previous.strip() in OCCASION_WORDS
                           or previous.strip().isdigit()):
        value *= 0.5
    # GitHub's main domain, not an arbitrary .com address or subdomain.
    domain = previous.lower().strip().lstrip('"/')
    if text == '.com' and domain == 'github':
        value = 1.3 if previous.startswith(' ') else 1.8
    elif text == '.com' and prev == 'ithub':
        value = 1.4
    elif text == ' com' and previous == 'package':
        value = -2.5
    elif text == '··' and (not previous or previous == '··'):
        value = 3.16
    return (doc, text, previous), float(value)

"""Recognize escape and TeX layout syntax, not ordinary prose.

A visible backslash has a modest positive response. Doubled backslashes
are strongly positive in escaped source strings but negative in TeX
line breaks. More deeply nested escaping has a smaller response.
NUL bytes also activate it. A few TeX layout-command prefixes are negative.
A document-opening Title header is strongly negative; other initial
tokens have a small negative baseline. The text buffer resets per document.
"""
import re

READS = ()
# Multi-letter control words distinguish TeX from one-letter string escapes.
TEX = re.compile(
    r'(?<!\\)\\(?![nrtxu])[a-z][A-Za-z]+'
    r'|\\(?:right|text|textbf|theta|times|nu|rho)\b'
)
# TeX row ending, suppressed equation number, horizontal layout, quad spacing.
LAYOUT_PREFIX = {
    'cr': -44.0,
    'non': -14.0,
    'h': -8.0,
    'q': -4.0,
}
DEEP_QUOTE = '\\' * 3 + '"'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = -0.5 if not tail else 0.0
    if tail == 'Title' and s == ':':
        value = -33.0
    elif '\x00' in s:
        value = 1.9
    elif '\\\\' in s:
        if not tail:
            value = 0.0
        elif TEX.search(tail) and not tail.endswith('\\"'):
            value = -21.0
        elif s.count('\\') > 2:
            value = 4.0 if s.count('\\') == 3 else 6.0
        elif tail.endswith('\\"'):
            value = 17.0
        elif DEEP_QUOTE in tail[-100:]:
            value = 9.0
        else:
            value = 13.0
    elif '\\' in s:
        if s.strip() == '\\':
            value = 0.9
        elif s.endswith('\\'):
            value = 0.5
        elif '\\"' in s:
            value = 0.75
    elif tail.endswith('\\') and not tail.endswith('\\\\'):
        value = LAYOUT_PREFIX.get(s, 0.0)
    elif tail.endswith('\\h') and s == 'line':
        value = -13.0
    return (doc, (tail + s)[-256:]), value

"""Approximate a GO-word and GO-syllable detector.

The main responses are to go, went, gone, goes and going. Previous
words change the strength: "has gone" exceeds "is gone", and "before
going" exceeds "is going". Go filenames, compounds, transliterations
and short go-shaped word pieces also receive positive predictions.
Across a token boundary, g + o (or Scandinavian å) also fires.
Repeated middle dots get a negative prediction; other tokens get zero.
"""
from functools import lru_cache
from anyascii import anyascii
import unicodedata

READS = ()
SONORANTS = frozenset('lmnrwy')
PRONOUNS = {'i', 'you', 'we', 'they', 'he', 'she', 'who'}
MODALS = {'can', 'could', 'will', 'would', 'should', 'may', 'might', 'must'}
PRESENT_BE = {'am', 'is', 'are', "'m", "'s", "'re", '’m', '’s', '’re'}
PAST_BE = {'was', 'were'}
HAVE = {'have', 'has', 'had', "'ve", "'d", '’ve', '’d'}
GERUND_INTRODUCERS = {
    'before', 'after', 'without', 'despite', 'by', 'of', 'on', 'for',
    'from', 'about', 'upon', 'into', 'through', 'since', 'while',
}


@lru_cache(maxsize=32768)
def spelling(text):
    return anyascii(text).lower()


def predict(token, previous):
    s = spelling(token)
    word = s.strip()
    p = previous.strip().lower()
    if word == 'went':
        return 7.3
    if word == 'goes':
        return 5.7
    if word == 'gone':
        if p in HAVE:
            return 8.6
        if p in PRESENT_BE | PAST_BE | {'be'}:
            return 5.0
        return 7.5
    if word == 'going':
        if p in PRESENT_BE:
            return 3.9
        if p in PAST_BE or p == 'not':
            return 4.7
        if p in GERUND_INTRODUCERS:
            return 8.4
        return 5.7
    if word == 'go':
        if not token.isascii():
            return 1.5
        if p in {'let', 'letting'}:
            return 2.2
        if p in {'not', "'t", '’t'} or p.endswith(("n't", 'n’t')):
            return 7.5
        if p in PRONOUNS | MODALS | {'to', 'and', 'also'}:
            return 6.3
        if previous and previous.isspace():
            return 3.0
        if p in {'&&', '`', '```'}:
            return 3.0
        if token.isupper():
            return 3.5
        if word != token.strip():
            return 4.2
        return 4.8 if token.startswith(' ') else 2.6
    if word == '.go':
        return 1.9
    if word in {'-go', '/go'}:
        return 3.1
    if word == '-going':
        return 8.1
    if word.startswith('undergo'):
        return 4.3 if word.endswith('ing') else 2.6
    if word in {'underwent', 'undergone'}:
        return 2.2
    if word.endswith('going'):
        return 3.4 if word.startswith('out') else 1.7
    if s and previous and not token[0].isspace():
        left = spelling(previous)
        alphabetic = ('LATIN', 'CYRILLIC', 'GREEK')
        g_letter = unicodedata.name(previous[-1], '').startswith(alphabetic)
        vowel_letter = unicodedata.name(token[0], '').startswith(alphabetic)
        if g_letter and vowel_letter and left.endswith('g'):
            if token[0].lower() == 'å':
                return 6.0
            if s.startswith('o'):
                if s.startswith(('od', 'ot')):
                    return 0.0
                value = 4.8 if len(s) <= 2 else 1.5
                if not token.isascii() or left.endswith('ng'):
                    value *= 0.5
                return value
        if (previous.isascii() and left.endswith('go')
                and s in {'ing', 'ings', 'er', 'ers'}):
            return 6.0
    if token.isascii() and word.endswith('go') and not token[0].isspace():
        if len(word) > 4:
            return 0.7
        return 4.0 if word.endswith('ngo') else 1.8
    if (token.isascii() and len(word) == 3
            and word.startswith('go') and word[-1] in SONORANTS):
        return 3.5
    if token and set(token) == {'·'} and len(token) >= 2:
        return -2.0
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if (len(prefix.token_ids) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    return None, predict(prefix.token_strings[-1], previous)

"""Sparse lexical cues, mainly in Chinese, Japanese, and Korean.

Possibility/necessity vocabulary and examination, experience, insurance, and
danger kanji give positive responses. Time spans, projects, and temptation
give negative ones. Recognize completed characters even across byte tokens;
keep a short text tail to distinguish kinds of experience. There are also
rules for an initial 12 and initial runs of repeated punctuation.
"""
import codecs
import regex

JAPANESE = regex.compile(r"[\p{Hiragana}\p{Katakana}]")

READS = ()


def lexical(text, tail):
    s = text.strip()
    # 可能 = possible; 必要 = necessary. Recent kana strengthens bare forms.
    if s == '可能':
        return 5.0 if JAPANESE.search(tail) else 3.4
    if '可能' in s:
        if s == '可能性':
            return 3.4
        if s.endswith('な'):
            return 0.6
        return 1.6 if s.endswith(('会', '會')) else 1.8
    if s == '能' and tail.endswith('可'):
        return 6.0
    if s == '必要':
        return 4.3 if JAPANESE.search(tail) else 1.0
    if '必要' in s:
        return 0.6 if s.endswith('な') else 1.8
    # Korean need / possibility.
    if s in ('필요', '가능'):
        return 2.3 if s == '필요' else 3.8
    # 験 = experience/test; 険 = danger; 検 = examine, with related forms.
    if s == '験':
        return 7.3 if tail.endswith('体') else 5.1
    if s in ('険', '險', '险'):
        return 5.5 if s == '険' else 4.3
    if s == '検':
        return 3.6
    if s in ('驗', '验'):
        return 2.4
    if s == '험':
        return 3.6
    if s in ('保险', '保險'):
        return 2.8
    if s in ('风险', '風險', '危險', '危险'):
        return 1.2
    if s in ('检测', '檢測', '检验', '檢驗'):
        return 0.3
    if s in ('或许', '或許', '也许', '也許', '的确', '的確', '可行'):
        return 1.7
    if s == '似乎':
        return 0.9
    if s in ('可说', '可說'):
        return 2.5
    # Negative duration, project, and temptation vocabulary.
    if s in ('期间', '期間', '期限'):
        return -0.6
    if s == '目的' and tail.endswith('項'):
        return -2.8
    if '项目' in s or '項目' in s:
        return -3.5 if '項目' in s else -1.1
    if s in ('诱惑', '誘惑'):
        return -0.7
    # Importance, emphasis, and speaking.
    if s == '重要':
        return 1.1
    if s in ('重点', '重點'):
        return 0.4
    if s in ('講', '讲'):
        return 1.7 if s == '講' else 0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, first, initial_run, pending, tail = 0, '', True, b'', ''
    else:
        _, n, first, initial_run, pending, tail = carry
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'replace', False)
    pending = raw[used:]
    value = lexical(text, tail)
    # Smaller response on the incomplete UTF-8 prefix shared with 験.
    if pending == '験'.encode('utf8')[:-1]:
        value = 1.45
    if n == 0:
        first = text
    initial_run = initial_run and text == first
    if initial_run and (text == '··' or text == '^^^^'):
        value = 3.04
    if n == 1 and first == '1' and text == '2':
        value = 3.51
    return (doc, n + 1, first, initial_run, pending,
            (tail + text)[-12:]), value

"""Respond to Slavic ne/nie spellings, often the beginning of negation.

The response is strongest at a word's beginning and also spans a token
boundary between n and e.  A z before e instead inhibits it. Latin spellings
are interpreted using the language of the preceding text; Russian spellings
are recognized directly. Short pieces immediately following ne can also
respond; longer word pieces and most small background activity are ignored.
This is a spelling heuristic, not a test for logical negation.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=20000)
def language_word(word, language):
    return zipf_frequency(word, language)


def language(text):
    # Exclude ne itself: it must not be its own evidence for a language.
    words = [w for w in re.findall(r'[^\W\d_]+', text.lower())[-16:]
             if len(w) > 1 and w not in ('ne', 'nie', 'nem')]
    if not words:
        return ''
    languages = ('cs', 'sk', 'pl', 'de', 'fr', 'en', 'it', 'pt', 'hu',
                 'nl', 'da', 'nb', 'tr', 'ro', 'es')
    scores = {lang: sum(language_word(w, lang) for w in words) / len(words)
              for lang in languages}
    best = max(scores, key=scores.get)
    if scores[best] < 2.0:
        return ''
    return best


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    prev, text = carry[1:] if same_document else ('', '')
    raw = prefix.token_strings[-1]
    token = raw.lower()
    s = token.strip()
    initial = token != s or not text or not text[-1:].isalpha()
    value = 0.0
    if prev == ' не' and not initial and token.isalpha() and len(token) <= 3:
        value = 8.7 if token in ('с', 'ч') else 3.3
    elif (prev in (' ne', ' nie') and token in ('z', 'v', 'j', 'ž', 'š')
          and language(text) in ('cs', 'sk', 'pl')):
        value = 8.0 if prev == ' nie' and token == 'z' else 4.5
    elif s == 'не':
        value = 10.4 if initial else 1.7
        if prev == ' а':
            value = 5.5
    elif initial and s in ('нед', 'нев', 'нек', 'неск'):
        value = 6.1
    elif initial and s in ('нет', 'нем', 'ни'):
        value = 2.8
    # Short Cyrillic syllables beginning with е, after н or з.
    elif (token.startswith('е') and len(token) in (2, 3)
          and token[1] not in 'йш'):
        p = prev.strip()
        if p == 'н' or prev.endswith('н'):
            word = re.search(r'[^\W\d_]+$', text.lower())
            word = word.group() if word else ''
            value = 9.5
            if token[1] in 'пзнл':
                value += 3.3
            elif token[1] == 'м':
                value -= 2.2
            elif token[1] == 'т':
                value -= 4.5
            elif token[1] == 'к':
                value -= 1.5
            if p != 'н':
                value *= 0.25
            elif word != 'н':
                value *= 0.5 if len(word) == 2 else 0.25
        elif p == 'з':
            value = -5.5
        elif prev.endswith('з'):
            value = -2.0
        if len(token) == 3:
            value *= 0.5
    # Latin ne/nie needs Slavic language evidence (not French ne, etc.).
    elif (not raw.isupper()
          and s in ('ne', 'nie', 'nem', 'ned', 'nel', 'nen', 'nep', 'nied')):
        lang = language(text)
        if (initial and lang in ('cs', 'sk', 'pl')
                and (s != 'ne' or raw.strip() != 'Ne' or lang != 'pl')):
            value = 10.0
        elif initial and s == 'nem' and lang == 'hu':
            value = 2.8
    # The same spelling split between Latin tokens.
    elif (raw == token and token.startswith(('e', 'ie', 'ě'))
          and len(token) <= 4 and prev.strip() in ('n', 'ni', 'z', 'zi')):
        p = prev.strip()
        if p in ('n', 'ni'):
            lang = language(text)
            value = 9.5 if lang in ('cs', 'sk', 'pl') else 0.0
            word = re.search(r'[^\W\d_]+$', text.lower())
            if word and word.group() not in ('n', 'ni'):
                value *= 0.25
            if p == 'ni':
                value *= 0.5
            if token.endswith('d'):
                value *= 0.3
        else:
            value = -3.5 if token.startswith(('em', 'ie')) else 0.0
        if token == 'ě':
            value = -1.5
            if p == 'n':
                value = 5.0 if word and word.group() == 'n' else 1.0
    elif token == 'ě':
        value = -1.5
    elif raw == 'Е' and prev.strip() == 'н':
        value = 13.0
    return (doc, token, (text + raw)[-240:]), value

programs.haiku:
"""Slavic negation detector: fires on the negation morpheme (не / ne / nie / nem) of Russian and Czech/Polish."""

READS = ()

WHOLE_WORDS = {"нет": 3.0, "нем": 2.5, "ни": 2.5}
LATIN_NEG = {"ne", "nie", "nem", "ned", "nen"}
SLAVIC_LETTERS = set("ěščřžůťďňľĺŕąęłśźżĚŠČŘŽŮ")


def _word_so_far(prefix):
    """Letters of the current word up to the newest token, within its document."""
    word = ""
    last_doc = prefix.document_ids[-1]
    for i in range(len(prefix.token_strings) - 1, -1, -1):
        if prefix.document_ids[i] != last_doc:
            break
        s = prefix.token_strings[i]
        k = 0
        while k < len(s) and not s[k].isalpha():
            k += 1
        word = s[k:] + word
        if k > 0 or not s:
            break
    return word.lower()


def _slavic_context(prefix):
    """True if the document so far contains Cyrillic or Czech/Polish letters."""
    last_doc = prefix.document_ids[-1]
    for i in range(len(prefix.token_strings) - 1, -1, -1):
        if prefix.document_ids[i] != last_doc:
            break
        for ch in prefix.token_strings[i]:
            if "Ѐ" <= ch <= "ӿ" or ch in SLAVIC_LETTERS:
                return True
    return False


def step(carry, prefix, upstream):
    word = _word_so_far(prefix)
