COORDINATORS = frozenset('and or but nor yet so'.split())
BE_FORMS = frozenset('am is are was were be being been'.split())
DECLARATIONS = frozenset('''
def class function var let const import from package using public private
protected static enum struct interface namespace module export
'''.split())
HAN = regex.compile(r'\p{Script=Han}')
LATIN = regex.compile(r'\p{Script=Latin}')
CYRILLIC = regex.compile(r'\p{Script=Cyrillic}')
