    if s.isspace():
        if '\n' in s:
            return 12.5 if s == '\n' else 9.5
        return 12.0 if s == ' ' else 19.5
    text = s.lstrip(' ')
    if not text:
        return 12.0
    c = text[0]
    if s.startswith(' '):
        if text in COORDINATORS:
            return 20.6
        if text in BE_FORMS:
            return 24.0
        if c.isalpha():
            if LATIN.match(c):
                return 29.3 if c.isupper() else 33.3
            return 26.7 if c.islower() or c.isupper() else 23.5
        return 18.0
    if text in DECLARATIONS:
        return 19.7
    if c.islower():
        return 14.2
    if c.isupper():
        return 12.8 if CYRILLIC.match(c) else 10.3
    if c.isdigit():
        return 11.0
    if c.isalpha():
        return 8.4 if HAN.match(c) else 13.2
