"""Audio-spelling detector.

The component responds to the letters a-u-d spelled out inside a word in the running text
of a document (the text is lower-cased, and Cyrillic look-alikes are read as Latin letters):
  * "aud" completing inside a word (Maud, Arnaud, fraud, Thebaud, Recaud): about +7 to +10,
    and about +3.5 when the "au" starts a word (Aud, aud);
  * a letter after "aud" (audi-, aude-, audit, audio): about +4; a letter after "audi": +2;
  * "aum" inside a word (Raum, Baum, Zeitraum): strongly negative, about -4.5 to -10;
  * other letters after "au" (aus, aub, auh, aup...): small positive or negative values.
Everything else is about zero.

The carry is the running text since the document began (its last few characters).
"""

READS = ()

LOOKALIKE = {"а": "a", "у": "u", "д": "d", "и": "i", "м": "m", "е": "e"}
AFTER_AU = {"d": 8.0, "m": -4.5, "v": 2.4, "ß": 3.0, "e": -0.9, "b": 0.7, "h": 0.9,
            "p": 1.0, "k": 1.0, "s": 0.5, "g": 0.3}
START_OF_WORD = 0.45  # weaker when the "au" starts a word
KEEP = 8  # characters of running text kept in the carry


def step(carry, prefix, upstream):
    tail = carry or ""
    docs = prefix.document_ids
    if len(docs) > 1 and docs[-1] != docs[-2]:
        tail = ""  # a new document: forget the text before it
    piece = prefix.token_strings[-1].lower()
    tail = (tail + "".join(LOOKALIKE.get(c, c) for c in piece))[-KEEP:]
    last = tail[-1:]
    if tail[-3:-1] == "au":
        value = AFTER_AU.get(last, 0.0)
        before = tail[-4:-3]  # the letter before the "au", if any
    elif tail[-4:-1] == "aud" and last.isalpha():
        value = 4.0
        before = tail[-5:-4]
    elif tail[-4:-1] == "aum" and last == "e":
        value = -4.0  # "aume", as in "royaume"
        before = tail[-5:-4]
    elif tail[-5:-1] == "audi" and last.isalpha():
        value = 2.0
        before = tail[-6:-5]
    else:
        return tail, 0.0
    if not before.isalpha():
        value *= START_OF_WORD
    return tail, float(value)

