        report, value = 'pass', -0.5
    elif word == 'PASS' and start:
        value = -0.4
    elif word == 'ok' and start:
        report, value = 'ok', -1.3
    elif word == 'ok' and re.search(r'(?:\.\.\.|test result:)\s*$', line):
        report, value = 'inline_ok', -2.0
    elif word == 'Ok':
        value = -2.7 if start else -0.35
    elif word in ('---', '===') and start:
        report = word
        value = -0.6 if word == '---' else -0.16
    elif token in ('>', ' >'):
        if line.endswith('#'):
            value = -2.6
        elif line.endswith(('Prelude', '*Main')):
            value = -6.5
        elif start or line.endswith('mysql'):
            value = -1.3
    elif low == '.log' and previous.strip().endswith('console'):
        value = -0.8
    elif low in ('.println', '.writeline', 'println'):
        value = -0.5
    elif low == 'print' and start:
        value = -0.1 if token.startswith(' ') else -0.25
    elif low in ('mock', 'expected'):
        value = -0.8 if start else (-0.25 if low == 'mock' else 0.0)
    elif low == '.raises' and 'pytest' in tail[-15:]:
        value = -0.9
    elif token == '!(' and re.search(r'assert_(?:eq|ne)$', tail):
        value = -1.1
    elif low == 'suites' and previous.strip() == 'test':
        value = -1.5
    if report:
        n = counts.get(report, 0)
        limits = {'pass': -2.3, 'ok': -3.0, 'inline_ok': -2.8,
                  '---': -1.5, '===': -0.38}
        value += (limits[report] - value) * n / (n + 2)
        counts[report] = n + 1
    if token != '\r':
        counts['content'] = True
    return (doc, (tail + token)[-160:], counts, token), value

programs.haiku:
"""Unit-test vocabulary: a negative response to assertion calls, test verdicts and
test-runner output markers.

The component's activation is near zero almost everywhere. It goes clearly negative on a
small set of tokens that belong to unit-test code and test-runner output:
  - the doctest prompt '>>>';
  - assertion calls: assert, assertEquals, assertThat, .assert, and the '_eq' of assert_eq
    (with the '!(' that opens its arguments);
  - JavaScript expect(...) and 'expected' messages;
  - verdict words in test results: ' ok', ' PASS', ' FAIL';
  - dash separators '---' and a '>' that starts a line (shell prompt or quote).
This program writes those values and zero elsewhere.
"""

READS = ()

DOCTEST_PROMPT = -16.0
ASSERT_CALL = -2.0
ASSERT_EQ_TAIL = -3.5
ARGS_AFTER_ASSERT = -1.3
EXPECT_CALL = -1.3
EXPECTED_MSG = -0.3
VERDICT = -1.7
DASH_RULE = -1.0
LINE_START_GT = -1.0


def is_assert(tok):
    word = tok.strip()
    return word.startswith("assert") and not word.startswith("assertion")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    word = tok.strip()
    spaced = tok[:1] == " "
    value = 0.0
    if ">>>" in tok:
        value = DOCTEST_PROMPT
    elif is_assert(tok) and word[6:7] != "s":
        value = ASSERT_CALL
    elif word == "_eq":
        value = ASSERT_EQ_TAIL
    elif word == "!(" and (is_assert(prev) or prev == "_eq"):
        value = ARGS_AFTER_ASSERT
    elif word == "expect" and spaced:
        value = EXPECT_CALL
    elif word == "expected" and spaced:
        value = EXPECTED_MSG
    elif word in ("ok", "Ok", "PASS", "FAIL") and spaced:
        value = VERDICT
    elif word == "---":
        value = DASH_RULE
    elif word == ">" and "\n" in prev:
        value = LINE_START_GT
    return carry, float(value)

programs.sol:
"""A local quantity-word and m-o spelling detector.

The negative response to 'more' is strongest after 'no', counts, 'or',
and information-seeking verbs; 'many'/'much' strengthen after degree words.
Short mo-like word pieces also respond negatively, including o after a
previous token ending in m. Continuation 'man' has the opposite sign.
These are approximate responses, not a general semantic quantity parser.
Only the preceding token is remembered, and documents reset that memory.
"""
from functools import lru_cache
import regex
import inflect
from anyascii import anyascii

READS = ()
_number_words = inflect.engine()
NUMBERS = frozenset(
    _number_words.number_to_words(n).split()[-1]
    for n in (*range(20), *range(20, 100, 10), 100, 1000, 10**6, 10**9)
)
QUANTIFIERS = frozenset('any few several couple many some'.split())
INFORMATION_VERBS = frozenset(
    'see read view find learn show load loading download add provide'.split()
)

@lru_cache(maxsize=32768)
def spelling(text):
    if regex.search(r'[\p{Script=Greek}\p{Script=Cyrillic}]', text):
        return anyascii(text).lower()
    return text.lower()


def response(text, previous):
    s, p = spelling(text), spelling(previous)
    w, prev = s.strip(' _'), p.strip()
    spaced = s != s.lstrip()
    capital = text.strip()[:1].isupper()

    # Quantity expressions: the previous word distinguishes common uses.
    if w == 'more':
        if not spaced:
            return -3.77 if p and p[-1].isalpha() else -1.27
        if prev == 'no':
            return -6.63
        if prev in NUMBERS or prev.isdigit() or prev in QUANTIFIERS:
            return -3.63
        if prev == 'or':
            return -2.62
        if prev == '//':
            return -4.25
        if prev in INFORMATION_VERBS:
            return -2.57 if previous.strip()[:1].isupper() else -1.48
        if prev == 'for':
            return -1.77
        if prev in {'even', 'lot'}:
            return -1.33
        return -0.49
    if w in {'many', 'much'}:
        many = w == 'many'
        if prev in {'not', 'no'}:
            return -2.17 if many else -2.75
        if prev == 'too':
            return -2.46 if many else -1.87
        if prev in {'so', 'as', 'infinitely'}:
            return -1.55 if many else -1.29
        return -0.08 if many else -0.12
    if w == 'most':
        return -0.40 if prev == 'the' else -0.15
    if w == 'anymore':
        return -2.43
    if text == '更多':
        return -3.29
    if w in {'más', 'mais', 'mehr'}:
        return -0.30

    # Short spelling fragments, distinguished from whole m-initial words.
    if w in {'mo', 'mor', 'mos'}:
        if not spaced and p.endswith('m'):
            return 0.16
        if spaced:
            if w == 'mo':
                return -0.60 if capital else -1.84
            if w == 'mor':
                return -0.40 if capital else -0.85
            return -2.65
        if w == 'mo':
            return -4.29 if p.endswith(('s', 'z', 'sh')) else -2.21
        return -0.88 if w == 'mor' else -0.70
    if not spaced and regex.fullmatch('[aeiou]mo', s):
        return -0.85
    if not spaced and regex.fullmatch('om[aeiou]', s):
        return -0.32
    if not spaced and s == 'man':
        if p.endswith(('s', 'z', 'sh', 'ch', 'x')):
            return 1.32
        if p.endswith(('l', 'r')):
            return 0.09
        if p.endswith(('n', 'm')):
            return 1.8
        return 0.59
    if not spaced and p.endswith('m') and s.startswith('o'):
        if s == 'ores':
            return -5.94
        if s == 'ore':
            return -2.1
        if s == 'o':
            return -1.25
        if s.startswith('os'):
            return -1.40
        if s.startswith('or'):
            return -0.64
        if s.startswith('ov'):
            return 0.18
        if len(s) <= 4:
            return -0.22
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    return (doc, text), response(text, previous)

"""A spelling-based detector for plural and polite ways of addressing people.

It gives negative responses to several languages' person/plural endings,
Japanese polite predicates, and formal pronouns. Word frequencies distinguish
Romance conjugations from similar-looking English word fragments. It is not
a parser: noun endings with the same spelling can respond too. Separate
rules cover middle-dot/CR padding, initial empty-comment headers, and a
positive response to the colon after a document-initial 'Title' label.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=4096)
def context_language(text):
    """A dictionary-frequency cue, using at most ten recent alphabetic words."""
    words = re.findall(r"[^\W\d_]+", text.lower())[-10:]
    # Include competing languages: German past-tense -te is not Czech address.
    languages = ('en', 'fr', 'es', 'pt', 'it',
                 'de', 'pl', 'tr', 'cs', 'sk')
    return max(languages, key=lambda lang: sum(
        zipf_frequency(w, lang) for w in words))


