            return -1.0  # Japanese copula
        return -1.2  # Japanese polite predicate
    if re.search(r'(?:니다|세요|십시오|요)$', s) or (attached and s == '다'):
        return -1.1  # Korean predicate
    if low.strip() in {'вы', 'вас', 'вам', 'ваш', 'ваша', 'ваши'}:
        return -0.45  # Russian formal pronoun
    if low.strip() in {'vous', '-vous', 'vos'}:
        if re.search(r'\bje(?: ne)?\s*$', tail, re.I):
            return -2.7  # French object pronoun
        return -1.0  # French formal pronoun
    if s.strip() == 'Sie':
        previous = re.search(r'(\w+)\s*$', tail)
