            return -5.0  # German inverted formal pronoun
        if previous and previous[1].lower() in {'falls', 'wenn'}:
            return -2.9  # German conditional formal pronoun
        return -0.2  # German other formal pronoun
    if low.strip() == 'wir':
        return -0.7  # German first person plural
    if low.strip() in {'tu', 'te', 'ye', 'vi'} and s[:1].isspace():
        return -0.3  # Other address pronoun
    if (whole if attached else low.strip()) in {
        'faites', 'dites', 'êtes', 'veuillez', 'avez', 'pouvez'
    }:
        return -3.1  # French irregular address
    if not attached:
        return 0.0
    if low == 'е' and word.endswith(
        ('ает', 'яет', 'ует', 'еет', 'ёт', 'будет', 'йдет', 'ймет')
    ):
        return -4.2  # Slavic -ете, split before the final vowel
    if low == 'ьте' or (low == 'те' and word.endswith(('й', 'ь', 'и'))):
        return -4.2  # Slavic imperative te
    if low.endswith('тесь') or (low == 'есь' and word.endswith('т')):
        return -2.2  # Slavic reflexive address
    if low in {'ите', 'ете', 'айте', 'уйте', 'йтесь', 'йте'}:
        return -2.3  # Slavic plural address
    if low in {'ți', 'ţi'}:
        return -1.4  # Romanian plural address
    if low == 'ε' and word.endswith('τ'):
        return -2.2  # Greek imperative
    if low == 'ند':
        return -1.9  # Persian third person plural
    if low == 'ید':
        return -0.5  # Persian second person plural
    if low == 'ون' and word.startswith(('ي', 'ت', 'ن')):
        return -3.1  # Arabic imperfect plural
    if low == 'وا':
        return -2.4  # Arabic perfect plural
    if low in {'رد', 'ود', 'هد', 'ست'} and re.search(
        '[پچژگ]|(?:که|در|از|می) ', tail
    ):
