    # Only interpret ambiguous Latin endings in an appropriate language context.
    if whole.endswith('ez') and len(low) <= 6:
        if context_language(tail + low) == 'fr':
            return -5.5 if low == 'z' else -3.7
    if (low.endswith('ons') and len(low) <= 5
            and not low.endswith(('tions', 'sions'))):
        if context_language(tail + low) == 'fr':
            return -1.5  # French first person plural
    if low in {'amos', 'emos', 'imos'}:
        return -0.6  # Iberian first person plural
    if low in {'iamo', 'amo', 'mo', 'ate', 'ete', 'ite', 'iate', 'te'}:
        language = context_language(tail + low)
        if language == 'it':
            return -0.8  # Italian plural ending
        if language in {'cs', 'sk'} and low in {'te', 'ete'}:
            return -3.5  # Czech / Slovak plural -te
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, tail = '', ''
    else:
        _, word, tail = carry
    s = prefix.token_strings[-1]
    value = response(s, word.lower(), tail)
    # Large responses also occur on these graphical padding/header patterns.
    if s == ':' and tail == 'Title':
        value = 12.4
    elif s == '\r' and not tail.strip('\r'):
        value = -8.4
    elif s == '//\n' and not tail:
        value = -12.2
    elif len(s) >= 2 and not (tail + s).strip('·'):
        value = -2.34
    tail = (tail + s)[-160:]
    word = re.split(r'[^\w\u0300-\u036f]', word + s)[-1][-64:]
    return (doc, word, tail), value

"""A sparse lexical predictor, including a few split-character spellings.

Strong positives mark 抽 (draw/extract) and split 誇 (boast). Chinese and
Japanese design spellings are positive, English design and management/control
words negative. Split 掲 (post/display) and a double middle dot are negative.
Split mathematical italic phi is positive too. Two unfinished
Chinese character encodings have positive responses before completion. Split
academic words (教養, 学姐, 교수) also receive a positive response.
Code-opening markers have separate document-initial responses. Other text
is zero: this is a partial account, not a general semantic classifier.
"""
READS = ()


def lexical(text, first):
    if first:
        if text == 'An':
            return 1.71
        if text == ' an':
            return 1.06
        if text in ('import', 'package'):
            return 0.79
        if text == '#include':
            return -0.71
        if text == 'def':
            return -1.43
        if text in ('/*', '/*\n'):
            return 0.93
        if text == '//\n':
            return 4.83
    word = text.strip()
    if word == '抽':
        return 2.78
    if word == '抽出':
        return 1.0
    if word in ('设计', '設計'):
        return 0.52
    if word.lower() == 'design':
        return -0.145
    if word == '管理':
        return -0.53
    if word == '控制':
        return -0.18
    if word == '管控':
        return -0.95
    if word == '··':
        return -0.56
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = b'' if first else carry[1]
    piece = prefix.token_bytes[-1]
    ending = previous + piece
    value = lexical(prefix.token_strings[-1], first)
    if len(piece) == 3:
        academic_words = ('教養', '学姐', '교수')
        if any(ending.endswith(w.encode('utf8')) for w in academic_words):
            value = 1.2
    if len(piece) == 1 and piece[0] >= 128:
        for character, response in (('誇', 4.0), ('掲', -1.35), ('𝜑', 0.83)):
            if ending.endswith(character.encode('utf8')):
                value = response
        # The first two bytes shared by the 情/惠 and 染 character groups.
        if ending.endswith('情'.encode('utf8')[:2]):
            value = 0.75
        elif ending.endswith('染'.encode('utf8')[:2]):
            value = 1.1
    return (doc, ending[-3:]), value

