            value += 1.6
    elif '發生' in word:
        value = 5.5
        if previous.endswith('不'):
            value += 1.6
    elif word.startswith('生') and previous.endswith(('发', '發', '発')):
        value = 7.5
    elif word.startswith('じ') and previous.endswith('生'):
        value = 4.4
    elif '발생' in word:
        value = 4.8
    elif word.strip() == 'sinh' and previous.endswith('phát'):
        value = 6.4
    elif word.strip() == 'ra' and previous.endswith('xảy'):
        value = 3.4
    elif word.strip() == 'xảy':
        value = 1.6
    elif word.endswith('ิด') and previous.endswith('เก'):
        value = 5.0
    elif word.strip() == 'เก':
        value = 1.6

    # Related life, origination, and publication vocabulary.
    elif '生活' in word:
        value = 0.7 if word.startswith('的') or word.endswith('的') else 1.3
    elif '产生' in word:
        value = 1.3
    elif '產生' in word:
        value = 0.6
    elif any(w in word for w in ('引发', '引發', '激发', '激發')):
        value = 1.0
    elif '発' in word:
        value = -1.0 if previous.endswith('開') else 2.5
    elif word == '發' and previous.endswith('開'):
        value = -1.7
    elif word.startswith('表') and previous.endswith(('发', '發', '発')):
        value = 3.0
    elif '发表' in word or '發表' in word:
        value = 1.0
    elif '发放' in word or '發放' in word:
        value = -1.9
    elif word.startswith('泡') and previous.endswith(('发', '發')):
        value = -2.1
    elif word.startswith('발') and previous.endswith('개'):
        value = -2.2

