    elif previous.endswith('Posted'):
        value = {'on': 8.8, 'in': 2.0, ':': 0.9}.get(word.strip(), 0.0)
    elif previous.endswith('Published') and word.strip() == 'by':
        value = -6.3
    elif previous.endswith('published') and word.strip() == 'by':
        value = -1.2
    elif previous.endswith('posted') and word.strip() == 'on':
        value = 0.4

    # A separate, reproducible response to strings of middle-dot punctuation.
