    elif token == '/com' and previous == '/java':
        value = -0.6
    elif token == '.com' and position >= 2:
        # A namespace prefix can precede the commercial namespace: br.com.
        declaration = prefix.token_strings[-3].strip()
        if declaration == 'package':
            value = -3.38 if position == 2 else -1.5
