        if word.istitle() and len(word) > 1:
            return -0.31 if token.startswith(' ') else -0.42
        return -0.09 if token.startswith(' ') else -0.22
    if word.isdecimal():
        return -0.12
    if not word.isascii():
        return -0.34
    return -0.14


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or document != carry[0]:
        position, first = 0, token
    else:
        position, first = carry[1] + 1, carry[2]
    value = -0.0025
    if position == 0:
        value = opening_value(token)
    elif position == 1 and first == 'Title' and token == ':':
        value = -9.8516
    return (document, position, first), value

"""Recognize a sparse mixture of conventional text-template completions.

The largest spike is the colon of a document-opening ``Title:`` field.
Other spikes mark diff headers, court names, patent-office boilerplate,
and a few code/web-page templates. These are literal phrase rules, not
an attempt to infer the topic of arbitrary prose. The rules retain a short
document suffix and otherwise use an almost-zero background. Document-opening
quotes, comment lines, and type tokens have separate offsets.
"""
import re

READS = ()

# Each entry names a complete, recognizable boilerplate phrase. The value
# is emitted only when the newest token completes that phrase.
PHRASES = (
    ('Pat. Nos', 0.69),
    ('invention relates', 0.94),
    ('Regarding claim', 2.01),
    ('Regarding Claim', 2.01),
    ('rejected under', 0.83),
    ('does not teach', 1.68),
    ('explicitly disclose', 2.03),
    ('examiner by telephone', 2.18),
    ('examiner’s supervisor', 1.64),
    ("examiner's supervisor", 1.64),
    ('theorem was proved', 5.15),
    ('Suggest Corrections', 2.61),
    ('code is contributed', 1.37),
    ('Question From', 2.35),
    ('DOCUMENT INFO', 2.36),
    ('Solution Summary', 1.43),
    ('[email protected', 0.91),
    ('user-images.githubusercontent', 1.25),
    ('begin-user-doc', 0.89),
)


def response(tail, token, position):
    text = tail + token
    if token == ':' and position == 1 and tail == 'Title':
        return 8.172

    # Unified diffs: the two hunk boundaries, range and file introducer.
    if token.strip() == '@@':
        return 1.21 if token.startswith(' ') else 0.61
    if token == ' -' and tail.endswith('@@'):
        return 1.34
    if token == 'git' and tail.endswith('diff --'):
        return 1.10

    # Formal court-name headers have a larger response than mentions in prose.
    if token.lower() == ' of' and tail.lower().endswith('court'):
        if tail.lower().endswith('united states court'):
            return 2.40
        if re.search(
            r'(?:^|\n|\\n|\\x0c)[ \t]*(?:In the )?(?:Supreme )?Court$',
            tail, re.I
        ):
            return 2.65
        return 0.35
    if token == ' COURT' and tail.endswith('UNITED STATES DISTRICT'):
        return 1.77

    if token == ' rejected' and re.search(
        r'\b[Cc]laim(?:s|\(s\))?\s+[\d,\s()/-]+'
        r'(?:and [\d,\s()/-]+)?(?:is|are|is/are|were previously)$', tail
    ):
        return 1.90
    if token == ' directed' and tail.endswith(' should be') and 'examiner' in tail:
        return 5.51
    if token == 'esModule' and re.search(r'defineProperty\([^\n]*["\']__$', tail):
        return 5.74
    if token == '\\x' and tail.endswith('\\n'):
        return 0.46
    if token == ' SET' and re.search(r'/\*!\d+$', tail):
        return 0.76
    if token in ('来源', '关键词') and tail.endswith('本文'):
        return 2.09

    # Scraped-page headings and a page counter's fraction separator.
    if token == ' From' and tail.strip() == 'More':
        return 5.52
    if token == 'Topics' and tail.endswith('Similar\n'):
        return 2.98
    if token == ' /' and re.search(r'\bPage\s*\d+$', tail):
        return 4.44
    for phrase, value in PHRASES:
        if text.endswith(phrase) and not tail.endswith(phrase):
            return value

    if position == 0:
        if token == '//\n':
            return 4.214
        if token == '“':
            return 1.507
        if token in ('int', 'string'):
            return 2.04
        if token.isascii() and token.isdigit():
            return -0.069
        return 0.088
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, position = '', 0
    else:
        _, tail, position = carry
    token = prefix.token_strings[-1]
    value = response(tail, token, position)
    return (doc, (tail + token)[-256:], position + 1), value

"""Sparse lexical approximation: global scope, Chinese era words, and title labels.

English world/international responses depend on capitalization. Chinese words
for global or national scope, the present era, and continuity receive negative
values. Engineering and committees have a small positive response. A document-initial
'Title:' label has a separate, much larger negative response at its colon.
This describes selected lexical responses, not all of the component's variation.
"""
from functools import lru_cache
import re
import cedict

READS = ()


@lru_cache(maxsize=8192)
def chinese_response(word):
    meanings = cedict.glosses(word)
    first = meanings[0].lower() if meanings else ''
    if first == 'world':
        return -1.55
    if first == 'international':
        return -1.7
    if re.search(r'overseas|abroad|sino-foreign', first):
        return -1.1
    if re.search(r'worldwide|whole world|global|internationaliz', first):
        return -0.75
    if first in {'domestic', 'whole nation'}:
        return -0.65
    if re.search(r'^modern|^century$|contemporary era', first):
        return -0.7
    if first in {'at the present time', 'the present time', 'last year', 'this year'}:
        return -0.6
    if first == 'continuous':
        return -1.5
    if any('committee' in meaning.lower() for meaning in meanings):
        return 0.5
    if first == 'engineering':
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '')
    _, position, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    value = chinese_response(word) if not word.isascii() else 0.0

    if word.lower() == 'world':
        value = (-0.58 if token.startswith(' ') else -0.14) if word[0].isupper() else 0.08
    elif word.lower() == 'international':
        value = -0.40 if word[0].isupper() else -0.12
    elif word == 'Cup' and previous.strip() == 'World':
        value = -0.8
    elif '世界' in word:
        value = -1.5 if '杯' not in word else -1.1

    # Recognize words whose last character is a separate token.
    if previous.endswith(('国', '國')) and word in {'际', '際', '外', '產'}:
        value = -2.2
    elif previous.endswith('世') and word == '博':
        value = -3.5
    if token == ':' and previous == 'Title' and position <= 2:
        value = -6.25
    return (doc, position + 1, token), value

"""Approximate exception syntax and a secondary spelling response.

Layout and punctuation separate exception-handling keywords from prose uses.
Exception names and testing helpers receive their own strengths; else is weak.
A second rule makes short z-containing word pieces and their immediate short
continuations negative in Romanian/Dutch-looking text, identified by dictionary
frequencies. Word-initial Arabic zay also receives a negative value.
Unmatched tokens get zero. State resets at document boundaries.
"""
import re
from wordfreq import zipf_frequency

READS = ()


def response(token, before):
    s = token.strip()
    word = s.lstrip('._(@{}/')
    w = word.lower()
    if word == 'IOException':
        return 12.0 if s.startswith('.') else 6.0
    if word.endswith('Exception') and word != 'Exception':
        return 1.5 if token[:1].isspace() else 4.5
    if w not in {'try', 'catch', 'throw', 'throws', 'raise', 'raises',
                 'except', 'exception', 'exceptions', 'finally',
                 'noexcept', 'else', 'elif'}:
        return 0.0
    # Treat displayed escape sequences as line layout too.
    context = before.replace('\\n', '\n').replace('\\r', '\n')
    context = context.replace('\\t', '\t')
    space = token[:len(token) - len(token.lstrip())]
    line = (context + space).rsplit('\n', 1)[-1]
    # Source listings can put line numbers before the indentation.
    at_start = bool(re.fullmatch(r'\s*(?:\d+\t\s*|[+-]\s*)?', line))
    end = context.rstrip()
    code = at_start or bool(re.search(
        r'[{}]|\b(?:def|import|return|public|private)\b', context[-160:]))
    if w in {'exception', 'exceptions'}:
        if s.startswith('.'):
            return 6.7
        if s.startswith('_'):
            return 1.8
        if word[:1].isupper():
            if not token[:1].isspace():
                return 1.3 if end.endswith('(') else 5.3
            return 1.8 if re.search(r'\bexcept$', end) else 4.1
        return 1.4 if code else 0.5
    if w == 'noexcept':
        return 5.0
    if w == 'raises':
        if word == 'Raises' and at_start:
            return 6.0
        if s.startswith('.'):
            return 4.6
        return 3.5 if s.startswith('_') else 0.0
    if w == 'throws':
        return 18.0 if end.endswith(')') else 15.0 if end.endswith('@') else 0.0
    if w == 'elif':
        return 0.3
    if word != w:  # Capitalized prose is not a programming keyword.
        return 0.0
    if w == 'else':
        if at_start or end.endswith('}'):
            return 1.05
        return 0.2 if code else -0.5 if token[:1].isspace() else 0.4
    if w == 'catch':
        return 8.6 if end.endswith('}') else 0.0
    if w == 'except':
        if at_start:
            return 8.0 if token[:1].isspace() else 4.6
        return 0.2
    if w == 'raise':
        return 7.0 if at_start else 4.0 if code else -0.3
    if w == 'throw':
        if re.search(r'\bshould$', end):
            return 4.5
        return 7.0 if at_start else 5.7 if code else 0.3
    if w == 'try':
        if at_start:
            return 2.8 if token[:1].isspace() else 0.5
        return 0.4 if code else -0.15
    if w == 'finally':
        return 4.7 if at_start or end.endswith('}') else -0.3
    return 0.0


LANGUAGES = ('en', 'nl', 'ro', 'lv', 'de', 'pl', 'fr', 'es',
             'it', 'tr', 'hu', 'cs', 'pt')


def z_fragment(token, before, last):
    word = token.strip()
    if word == 'ز':  # Arabic zay.
        return -1.8 if token[:1].isspace() else 0.0
    if not (1 < len(word) <= 5 and word.isascii() and word.isalpha()):
        return 0.0
    direct = 'z' in word.lower()
    after = (not token[:1].isspace() and last[-1:].isalpha()
             and 'z' in last.lower())
    if not (direct or after):
        return 0.0
    # Compare familiar words, not an unrestricted learned language classifier.
    words = re.findall(r'[^\W\d_]{3,}', before.lower())[-14:]
    if not words:
        return 0.0
    scores = [sum(max(0, zipf_frequency(w, lang) - 2) for w in words)
              for lang in LANGUAGES]
    language = LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]
    if language not in {'ro', 'nl'}:
        return 0.0
    if direct:
        if language == 'nl':
            return -3.3
        return -4.5 if word.islower() else -2.5
    return -1.6 if word.islower() else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same = carry is not None and carry[0] == doc
    before, last = (carry[1], carry[2]) if same else ('', '')
    token = prefix.token_strings[-1]
    value = response(token, before)
    if value == 0:
        value = z_fragment(token, before, last)
    return (doc, (before + token)[-250:], token), value

