    '职责': 3.5,        # responsibilities
    '职能': 2.8,        # function
    '职权': 2.8,        # powers of office
    '职工': 4.7,        # employees
    '专职': 4.7,        # full-time employment
    '兼职': 3.6,        # part-time employment
    '职称': 4.7,        # professional title
    '职员': 4.7,        # staff
    '职场': 0.7,        # workplace
    '离职': 1.3,        # leaving a job
